insert into public.stilnytsi_materials (slug, data, position) values ('grey-ukraine', '{"slug":"grey-ukraine","name":"Покостівський граніт (Grey Ukraine)","material":"granit","family":"Граніт","origin":"Покостівське родовище, Україна","tone":"світло-сірий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади","бруківка"],"description":"Покостівський граніт — найпоширеніший український камінь для стільниць, сходів і фасадів. Світло-сіре дрібнозернисте тіло з рівномірними чорними вкрапленнями, без виразного рисунка, тому добре поєднується з будь-якими фасадами і не набридає. Полірований працює в інтер’єрі, термооброблений — на ґанках і терасах. Радіаційний I клас, стабільні партії, доступна ціна.","image":"/materials/grey-ukraine.webp","cardImage":"/materials/grey-ukraine.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":3640,"unit":"пог.м","currency":"грн"}}'::jsonb, 0) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('kometa-black', '{"slug":"kometa-black","name":"Габро (Kometa Black)","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"чорний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","каміни","фасади"],"description":"Габро Kometa Black — темна щільна порода з Житомирщини, яка після полірування стає майже чорною з ледь помітними сірими зернами. Витримує гаряче й удари краще за більшість темних імпортних гранітів і не має «рудих» вкраплень. У термообробленому фініші набуває глибокого сірого тону і стає протиковзким, тому це наш базовий вибір для вхідних сходів і каміних подіумів.","image":"/materials/kometa-black.webp","cardImage":"/materials/kometa-black.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":3900,"unit":"пог.м","currency":"грн"}}'::jsonb, 1) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('volga-blue', '{"slug":"volga-blue","name":"Лабрадорит Volga Blue","material":"granit","family":"Лабрадорит","origin":"Житомирська область, Україна","tone":"чорно-синій","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","каміни","фасади"],"description":"Лабрадорит Volga Blue — камінь із великими кристалами, що спалахують синім, зеленим і золотим під кутом до світла. У полірованому вигляді один із найефектніших матеріалів каталогу: стійки кафе, острови, портали камінів, стіни біля телевізора. За твердістю не поступається граніту, але через великі кристали кромку робимо з фаскою або скругленням.","image":"/materials/volga-blue.webp","cardImage":"/materials/volga-blue.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":6000,"unit":"пог.м","currency":"грн"}}'::jsonb, 2) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('irina-blue', '{"slug":"irina-blue","name":"Лабрадорит Irina Blue","material":"granit","family":"Лабрадорит","origin":"Житомирська область, Україна","tone":"темно-синій","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","фасади"],"description":"Лабрадорит Irina Blue — темніший і спокійніший родич Volga Blue: дрібніші кристали, рівномірніший синій відблиск, менше золотого. Підходить, коли потрібен темний камінь із життям усередині, але без надто контрастних спалахів. Стільниці, підвіконня, облицювання каміна, вертикальні поверхні.","image":"/materials/irina-blue.webp","cardImage":"/materials/irina-blue.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":5200,"unit":"пог.м","currency":"грн"}}'::jsonb, 3) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('carpazi', '{"slug":"carpazi","name":"Токівський граніт Carpazi","material":"granit","family":"Граніт","origin":"Дніпропетровська область, Україна","tone":"червоно-коричневий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["фасади","бруківка"],"description":"Токівський граніт Carpazi — червоно-коричневий камінь із Дніпропетровщини з характерним крупним зерном. Належить до II класу за радіаційним контролем, тому продаємо його виключно для зовнішніх робіт: бруківка, бордюри, цоколі, підпірні стіни, доріжки. На вулиці показує себе чудово: щільний, морозостійкий, не вигорає.","image":"/materials/carpazi.webp","cardImage":"/materials/carpazi.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"exteriorOnly":true}'::jsonb, 4) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('rosso-santiago', '{"slug":"rosso-santiago","name":"Капустинський граніт Rosso Santiago","material":"granit","family":"Граніт","origin":"Кіровоградська область, Україна","tone":"малиново-червоний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Капустинський граніт Rosso Santiago — малиново-червоний камінь із Кіровоградщини з дрібними чорними й сірими вкрапленнями. Один із найвідоміших українських гранітів у Європі. У полірованому вигляді дає насичений теплий колір для стільниць і сходів, у термообробленому — спокійніший бордовий відтінок для фасадів і вхідних груп.","image":"/materials/rosso-santiago.webp","cardImage":"/materials/rosso-santiago.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":2030,"unit":"м²","currency":"грн"}}'::jsonb, 5) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('maple-red', '{"slug":"maple-red","name":"Лезниківський граніт Maple Red","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"яскраво-червоний","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","сходи","фасади"],"description":"Лезниківський граніт Maple Red — яскраво-червоний із чорним і білим зерном, найконтрастніший із українських червоних гранітів. Використовується для акцентів: сходи, цоколі, смуги в бруківці, стільниці в теплих інтер’єрах. Термооброблений Maple Red стає цегляно-червоним і чудово поєднується з сірим Grey Ukraine у мощенні.","image":"/materials/maple-red.webp","cardImage":"/materials/maple-red.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":2200,"unit":"м²","currency":"грн"}}'::jsonb, 6) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('star-of-ukraine', '{"slug":"star-of-ukraine","name":"Дідковицький граніт Star of Ukraine","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"рожево-коричневий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","фасади"],"description":"Дідковицький граніт Star of Ukraine — рожево-коричневий камінь із мʼяким переливом зерна, який виглядає спокійніше за червоні породи, але тепліше за сірі. Добре працює на великих площинах: стільниці, підвіконня, фасадні плити, підлога в передпокоях. I клас, стабільна поставка.","image":"/materials/star-of-ukraine.webp","cardImage":"/materials/star-of-ukraine.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":2620,"unit":"пог.м","currency":"грн"}}'::jsonb, 7) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('flower-of-ukraine', '{"slug":"flower-of-ukraine","name":"Межиріцький граніт Flower of Ukraine","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"червоно-рожевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["фасади","сходи","бруківка"],"description":"Межиріцький граніт Flower of Ukraine — червоно-рожевий із виразним крупним зерном, за яке його й назвали «квіткою». Найчастіше йде на фасади, сходи і бруківку, де крупний рисунок читається з відстані. У термообробленому фініші дає теплу рожеву поверхню, стійку до морозу й солі.","image":"/materials/flower-of-ukraine.webp","cardImage":"/materials/flower-of-ukraine.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 8) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('leopard', '{"slug":"leopard","name":"Корнинський граніт Leopard","material":"granit","family":"Граніт","origin":"Житомирська область, Україна","tone":"рожевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["фасади","сходи","підвіконня"],"description":"Корнинський граніт Leopard — рожевий камінь із характерними темними «плямами», схожими на хутро леопарда. Декоративний і при цьому недорогий матеріал для фасадів, цоколів, сходів і підвіконь. Термооброблений Leopard особливо добре виглядає на великих зовнішніх площинах.","image":"/materials/leopard.webp","cardImage":"/materials/leopard.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 9) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('bianco-carrara', '{"slug":"bianco-carrara","name":"Мармур Bianco Carrara","material":"marmur","family":"Мармур","origin":"Італія","tone":"білий із сірими прожилками","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["ванна","каміни","підвіконня"],"description":"Мармур Bianco Carrara — класичний італійський камінь із Апуанських Альп: світло-сірий фон із м’якими сірими прожилками. Універсальний вибір для ванних кімнат, підвіконь, каміних порталів і столиків. Радимо матовий (honed) фініш: на ньому не видно слідів води й кислот, а сам камінь виглядає ще благородніше.","image":"/materials/bianco-carrara.webp","cardImage":"/materials/bianco-carrara.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":240,"unit":"м²","currency":"€"}}'::jsonb, 10) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('crema-marfil', '{"slug":"crema-marfil","name":"Мармур Crema Marfil","material":"marmur","family":"Мармур","origin":"Іспанія","tone":"кремово-бежевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["ванна","підлога","підвіконня"],"description":"Мармур Crema Marfil — іспанський кремово-бежевий камінь із ледь помітними прожилками. Найпрактичніший із мармурів для вологих зон: теплий тон ховає вапняний наліт і краплі, а спокійний рисунок не сперечається з іншими матеріалами. Ванни, підвіконня, підлога, облицювання стін.","image":"/materials/crema-marfil.webp","cardImage":"/materials/crema-marfil.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 11) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('emperador-dark', '{"slug":"emperador-dark","name":"Мармур Emperador Dark","material":"marmur","family":"Мармур","origin":"Іспанія","tone":"темно-коричневий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["ванна","каміни"],"description":"Мармур Emperador Dark — темно-коричневий іспанський камінь із мереживом світлих прожилок. Глибокий насичений матеріал для акцентів: стіна за умивальником, портал каміна, полиці, столики. У поєднанні зі світлим Crema Marfil дає класичну теплу пару для ванної або передпокою.","image":"/materials/emperador-dark.webp","cardImage":"/materials/emperador-dark.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 12) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('nero-marquina', '{"slug":"nero-marquina","name":"Мармур Nero Marquina","material":"marmur","family":"Мармур","origin":"Іспанія","tone":"чорний із білими прожилками","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["ванна","каміни"],"description":"Мармур Nero Marquina — чорний іспанський камінь із контрастними білими прожилками, найграфічніший із мармурів. Портали камінів, стільниці під накладну раковину, стінові панелі, консолі. На полірованій поверхні помітні краплі води й сліди кислот, тому для активних зон радимо матовий фініш або обережний догляд.","image":"/materials/nero-marquina.webp","cardImage":"/materials/nero-marquina.webp","care":"Нейтральний pH, просочення та негайне видалення кислот.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"}}'::jsonb, 13) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('taj-mahal', '{"slug":"taj-mahal","name":"Кварцит Taj Mahal","material":"kvarcyt","family":"Кварцит","origin":"Бразилія","tone":"кремово-бежевий","finishes":["полірований","шліфований"],"thicknesses":[20,30],"applications":["стільниці","острови","ванна"],"description":"Кварцит Taj Mahal — бразильський камінь кремово-бежевого тону з золотавими хвилястими прожилками. Виглядає як мармур, а працює як граніт: твердість 7 за Моосом, стійкість до кислот і гарячого посуду. Найкращий вибір для світлої кухні й острова, коли потрібен природний камінь без компромісів у практичності.","image":"/materials/taj-mahal.webp","cardImage":"/materials/taj-mahal.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":650,"unit":"м²","currency":"€"}}'::jsonb, 14) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('caesarstone-4001-fresh-concrete', '{"slug":"caesarstone-4001-fresh-concrete","name":"Caesarstone 4001 Fresh Concrete","material":"kvarc","family":"Кварц","origin":"Caesarstone","tone":"сірий бетон","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Caesarstone 4001 Fresh Concrete — кварцова поверхня з фактурою свіжого бетону: сірий тон із ледь помітною текстурою і матовим фінішем. Для сучасних кухонь, лофтів і ванних, де потрібна спокійна однорідна площина без блиску. Не має пор, не потребує просочення, гаряче — через підставку.","image":"/materials/caesarstone-4001-fresh-concrete.webp","cardImage":"/materials/caesarstone-4001-fresh-concrete.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Caesarstone"}'::jsonb, 15) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('caesarstone-5171-arabetto', '{"slug":"caesarstone-5171-arabetto","name":"Caesarstone 5171 Arabetto","material":"kvarc","family":"Кварц","origin":"Caesarstone","tone":"білий мармуроподібний","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Caesarstone 5171 Arabetto — білий кварц із тонкими сіро-бежевими прожилками, натхненний мармуром Arabescato. Дає світлу кухню з характером мармуру без його чутливості до кислот. Полірована поверхня, стабільний декор у межах партії, зручно поєднувати з дерев’яними і темними фасадами.","image":"/materials/caesarstone-5171-arabetto.webp","cardImage":"/materials/caesarstone-5171-arabetto.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Caesarstone"}'::jsonb, 16) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('caesarstone-5151-empira-white', '{"slug":"caesarstone-5151-empira-white","name":"Caesarstone 5151 Empira White","material":"kvarc","family":"Кварц","origin":"Caesarstone","tone":"білий із прожилками","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Caesarstone 5151 Empira White — чистий білий кварц із контрастними сірими прожилками, одна з найпопулярніших колекцій «під Калакату». Для просторих світлих кухонь і островів, де рисунок працює як головний акцент. Непористий, легкий у догляді, гаряче — лише через підставку.","image":"/materials/caesarstone-5151-empira-white.webp","cardImage":"/materials/caesarstone-5151-empira-white.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Caesarstone"}'::jsonb, 17) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('caesarstone-calacatta-nuvo', '{"slug":"caesarstone-calacatta-nuvo","name":"Caesarstone Calacatta Nuvo","material":"kvarc","family":"Кварц","origin":"Caesarstone","tone":"білий Calacatta","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Caesarstone Calacatta Nuvo — преміальний кварц із широкими сірими прожилками на білому тлі, найближчий до справжньої Калакати серед інженерних поверхонь. Для островів і довгих стільниць із мінімумом швів, у форматі Jumbo. Повністю непористий, стабільний колір, стійкий до плям.","image":"/materials/caesarstone-calacatta-nuvo.webp","cardImage":"/materials/caesarstone-calacatta-nuvo.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":20148,"unit":"м²","currency":"грн"},"brand":"Caesarstone"}'::jsonb, 18) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('vicostone-bq8270-calacatta', '{"slug":"vicostone-bq8270-calacatta","name":"Vicostone BQ8270 Calacatta","material":"kvarc","family":"Кварц","origin":"Vicostone","tone":"білий Calacatta","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Vicostone BQ8270 Calacatta — білий кварц із м’якими сірими прожилками у стилі італійського мармуру, доступніша альтернатива преміальним колекціям. Найчастіший вибір для сімейних кухонь у новобудовах: світло, практично, легко прибирається. Формат сляба дозволяє стільницю до 3 м без шва.","image":"/materials/vicostone-bq8270-calacatta.webp","cardImage":"/materials/vicostone-bq8270-calacatta.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Vicostone"}'::jsonb, 19) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('vicostone-bq8220-carrara', '{"slug":"vicostone-bq8220-carrara","name":"Vicostone BQ8220 Carrara","material":"kvarc","family":"Кварц","origin":"Vicostone","tone":"білий із сірим","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Vicostone BQ8220 Carrara — світлий кварц із дрібним сірим рисунком, який повторює мармур Carrara, але не має пор і не реагує на кислоти. Спокійна поверхня для кухонь, ванних і підвіконь у будь-якому стилі. Одна з найдоступніших світлих колекцій каталогу.","image":"/materials/vicostone-bq8220-carrara.webp","cardImage":"/materials/vicostone-bq8220-carrara.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Vicostone"}'::jsonb, 20) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('vicostone-bq8740-nero-marquina', '{"slug":"vicostone-bq8740-nero-marquina","name":"Vicostone BQ8740 Nero Marquina","material":"kvarc","family":"Кварц","origin":"Vicostone","tone":"чорний із білим","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Vicostone BQ8740 Nero Marquina — чорний кварц із білими прожилками за мотивами іспанського мармуру. Для контрастних кухонь, барних стійок, ванних із темним акцентом. На відміну від природного Marquina не боїться лимона й вина, але на глянці видно відбитки, тому витирати варто насухо.","image":"/materials/vicostone-bq8740-nero-marquina.webp","cardImage":"/materials/vicostone-bq8740-nero-marquina.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Vicostone"}'::jsonb, 21) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('vicostone-vivalioro', '{"slug":"vicostone-vivalioro","name":"Vicostone Vivalioro","material":"kvarc","family":"Кварц","origin":"Vicostone","tone":"кремовий із золотим","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Vicostone Vivalioro — кремовий кварц із золотистими й сірими прожилками, теплий і пластичний декор для кухонь у класичному або сучасному стилі з дерев’яними фасадами. Непористий, стійкий до плям, приємний у поєднанні з латунню й теплим світлом.","image":"/materials/vicostone-vivalioro.webp","cardImage":"/materials/vicostone-vivalioro.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Vicostone"}'::jsonb, 22) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('silestone-eternal-calacatta-gold', '{"slug":"silestone-eternal-calacatta-gold","name":"Silestone Eternal Calacatta Gold","material":"kvarc","family":"Кварц","origin":"Silestone","tone":"білий із золотим","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Silestone Eternal Calacatta Gold — білий кварц із сіро-золотими прожилками серії Eternal з підвищеною стійкістю до ультрафіолету й плям. Для світлих кухонь, де стільниця стоїть біля великого вікна, і для островів, які мають виглядати як мармур без його догляду.","image":"/materials/silestone-eternal-calacatta-gold.webp","cardImage":"/materials/silestone-eternal-calacatta-gold.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Silestone"}'::jsonb, 23) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('silestone-ethereal-glow', '{"slug":"silestone-ethereal-glow","name":"Silestone Ethereal Glow","material":"kvarc","family":"Кварц","origin":"Silestone","tone":"світлий теплий","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Silestone Ethereal Glow — світлий теплий кварц із ледь помітними м’якими прожилками серії Ethereal, ефект розсіяного світла на поверхні. Для спокійних мінімалістичних кухонь і ванних, де важлива однорідність без «стерильної» білизни.","image":"/materials/silestone-ethereal-glow.webp","cardImage":"/materials/silestone-ethereal-glow.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Silestone"}'::jsonb, 24) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('silestone-blanco-zeus', '{"slug":"silestone-blanco-zeus","name":"Silestone Blanco Zeus","material":"kvarc","family":"Кварц","origin":"Silestone","tone":"чистий білий","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Silestone Blanco Zeus — чистий білий кварц без рисунка, еталон однорідної білої поверхні. Для кухонь у стилі мінімалізм, лабораторно чистих ванних і торгових стійок. Показує кожну крихту, зате миється за секунду і не має жодних пор.","image":"/materials/silestone-blanco-zeus.webp","cardImage":"/materials/silestone-blanco-zeus.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Silestone"}'::jsonb, 25) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('silestone-eternal-marquina', '{"slug":"silestone-eternal-marquina","name":"Silestone Eternal Marquina","material":"kvarc","family":"Кварц","origin":"Silestone","tone":"чорний","finishes":["полірований","матовий"],"thicknesses":[20,30],"applications":["стільниці","острови","підвіконня"],"description":"Silestone Eternal Marquina — чорний кварц із білими прожилками серії Eternal з покращеною стійкістю до плям і UV. Драматичний акцент для островів, барних стійок і стільниць у темних кухнях. Не потребує просочення, гаряче — через підставку.","image":"/materials/silestone-eternal-marquina.webp","cardImage":"/materials/silestone-eternal-marquina.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Silestone"}'::jsonb, 26) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('laminam-calacatta', '{"slug":"laminam-calacatta","name":"Laminam Calacatta","material":"keramohranit","family":"Керамограніт","origin":"Італія","tone":"білий мармуроподібний","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Laminam Calacatta — великоформатний керамограніт 1620 × 3240 мм із декором білого мармуру з сірими прожилками. Плита 12 мм не боїться гарячого посуду, ножів, кислот і сонця. Для стільниць із тонким торцем, фартухів на всю стіну, фасадів меблів і облицювання без швів.","image":"/materials/laminam-calacatta.webp","cardImage":"/materials/laminam-calacatta.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Laminam","formats":["1620×3240"]}'::jsonb, 27) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('laminam-nero-marquina', '{"slug":"laminam-nero-marquina","name":"Laminam Nero Marquina","material":"keramohranit","family":"Керамограніт","origin":"Італія","tone":"чорний із білими прожилками","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Laminam Nero Marquina — чорний керамограніт великого формату з білими прожилками під іспанський мармур. Термостійкий, непористий, стабільний до UV, тому підходить і для кухні, і для літньої тераси. Тонка плита 12 мм у склеєній кромці виглядає як масивний камінь без ваги.","image":"/materials/laminam-nero-marquina.webp","cardImage":"/materials/laminam-nero-marquina.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Laminam","formats":["1620×3240"]}'::jsonb, 28) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('laminam-pietra-grey', '{"slug":"laminam-pietra-grey","name":"Laminam Pietra Grey","material":"keramohranit","family":"Керамограніт","origin":"Італія","tone":"темно-сірий","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Laminam Pietra Grey — темно-сірий керамограніт із м’якою природною текстурою каменю. Спокійний нейтральний матеріал для стільниць, прилавків, стін і підлог у комерційних та житлових інтер’єрах. Не боїться води, землі, гарячого й миючих засобів, тому часто йде в кафе і квіткові крамниці.","image":"/materials/laminam-pietra-grey.webp","cardImage":"/materials/laminam-pietra-grey.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Laminam","formats":["1620×3240"]}'::jsonb, 29) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('laminam-travertino', '{"slug":"laminam-travertino","name":"Laminam Travertino","material":"keramohranit","family":"Керамограніт","origin":"Італія","tone":"бежевий","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Laminam Travertino — бежевий керамограніт із декором травертину, але без його пор і потреби в просоченні. Дає теплу середземноморську фактуру столам, стільницям, стінам і навіть підлозі патіо, витримуючи мороз і воду. Великий формат дозволяє обійтись без швів на площинах до 3,2 м.","image":"/materials/laminam-travertino.webp","cardImage":"/materials/laminam-travertino.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Laminam","formats":["1620×3240"]}'::jsonb, 30) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('neolith-arctic-white', '{"slug":"neolith-arctic-white","name":"Neolith Arctic White","material":"keramohranit","family":"Керамограніт","origin":"Іспанія","tone":"білий","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Neolith Arctic White — чисто білий спечений камінь великого формату з матовою або полірованою поверхнею. Для стільниць, господарських і медичних приміщень, торгових стійок, де важливі гігієна й стійкість до хімії. Не вбирає нічого, миється будь-якими засобами, витримує гаряче.","image":"/materials/neolith-arctic-white.webp","cardImage":"/materials/neolith-arctic-white.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Neolith","formats":["1620×3240"]}'::jsonb, 31) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('neolith-calacatta', '{"slug":"neolith-calacatta","name":"Neolith Calacatta","material":"keramohranit","family":"Керамограніт","origin":"Іспанія","tone":"білий мармуроподібний","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Neolith Calacatta — великоформатний спечений камінь із декором білої Калакати з сірими й золотими прожилками. Одна з найреалістичніших імітацій мармуру серед керамічних поверхонь, доступна у полірованому та шовковистому фінішах. Стільниці, стіни, фасади меблів, облицювання без швів.","image":"/materials/neolith-calacatta.webp","cardImage":"/materials/neolith-calacatta.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Neolith","formats":["1620×3240"]}'::jsonb, 32) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('neolith-iron-corten', '{"slug":"neolith-iron-corten","name":"Neolith Iron Corten","material":"keramohranit","family":"Керамограніт","origin":"Іспанія","tone":"іржаво-коричневий","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Neolith Iron Corten — керамограніт із фактурою іржавої кортенівської сталі: рудий, коричневий, графітовий у одній плиті. Ефектний матеріал для фасадів, стін, барних стійок і зовнішніх кухонь. На відміну від справжнього кортену не бруднить руки і не стікає іржею по стіні.","image":"/materials/neolith-iron-corten.webp","cardImage":"/materials/neolith-iron-corten.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Neolith","formats":["1620×3240"]}'::jsonb, 33) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('neolith-estatuario', '{"slug":"neolith-estatuario","name":"Neolith Estatuario","material":"keramohranit","family":"Керамограніт","origin":"Іспанія","tone":"білий із сірими прожилками","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Neolith Estatuario — білий спечений камінь із виразними сірими прожилками під мармур Statuario, найконтрастніший із декорів Neolith. Для островів і стін, де потрібен «мармуровий» рисунок великого масштабу без ризику плям і травлення. Термостійкий, непористий, стабільний на сонці.","image":"/materials/neolith-estatuario.webp","cardImage":"/materials/neolith-estatuario.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Neolith","formats":["1620×3240"]}'::jsonb, 34) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('dekton-kreta', '{"slug":"dekton-kreta","name":"Dekton Kreta","material":"keramohranit","family":"Керамограніт","origin":"Іспанія","tone":"цементно-сірий","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Dekton Kreta — ультракомпактна поверхня Cosentino з фактурою цементу сірого тону. Спечена з мінералів під високим тиском, тому витримує гаряче, удари по площині, ультрафіолет і мороз. Для кухонь, літніх кухонь, фасадів і підлоги терас.","image":"/materials/dekton-kreta.webp","cardImage":"/materials/dekton-kreta.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Dekton","formats":["1620×3240"]}'::jsonb, 35) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('dekton-laurent', '{"slug":"dekton-laurent","name":"Dekton Laurent","material":"keramohranit","family":"Керамограніт","origin":"Іспанія","tone":"чорний із золотим","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Dekton Laurent — чорна ультракомпактна поверхня з тонкими золотистими прожилками за мотивами мармуру Port Laurent. Розкішний акцент для острова, барної стійки або стіни біля каміна. Не вбирає, не травиться, не вигорає; поліроване покриття потребує лише витирання насухо.","image":"/materials/dekton-laurent.webp","cardImage":"/materials/dekton-laurent.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Dekton","formats":["1620×3240"]}'::jsonb, 36) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_materials (slug, data, position) values ('dekton-rem', '{"slug":"dekton-rem","name":"Dekton Rem","material":"keramohranit","family":"Керамограніт","origin":"Іспанія","tone":"білий із прожилками","finishes":["матовий","полірований"],"thicknesses":[6,12],"applications":["стільниці","фасади","облицювання"],"description":"Dekton Rem — світла ультракомпактна поверхня з м’якими сірими й бежевими прожилками, спокійніша за Калакату. Для світлих кухонь і ванних, де рисунок має підтримувати простір, а не домінувати. Стійкий до всього, що трапляється на кухні, включно з гарячим посудом і ножами.","image":"/materials/dekton-rem.webp","cardImage":"/materials/dekton-rem.webp","care":"Нейтральний засіб; для природного каменю перевіряти просочення.","relatedArticles":["yak-vybraty-kamin-dlya-kukhni","yak-doglyadaty-za-granitnoyu-stilnytseyu"],"relatedCategories":["stilnytsi","fasady"],"price":{"value":0,"unit":"м²","currency":"грн"},"brand":"Dekton","formats":["1620×3240"]}'::jsonb, 37) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_projects (slug, data, position) values ('kitchen-everyday', '{"slug":"kitchen-everyday","name":"Кухня на щодень","type":"Стільниця","material":"Vicostone BQ8270 Calacatta","materialSlug":"vicostone-bq8270-calacatta","location":"Рівне","story":"Для родини в новобудові потрібна стільниця, яку не треба жаліти: світлий кварц легко прибирати після щоденного готування.","solution":"Г-подібна стільниця, мийка нижнього монтажу, короткий фартух.","image":"/proposals/kitchen-everyday.webp","gallery":["/proposals/kitchen-everyday.webp","/proposals/kitchen-everyday.webp","/detail-stone-edge.webp"],"alt":"Стандартна кухня у новобудові зі стільницею Vicostone BQ8270 Calacatta"}'::jsonb, 0) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_projects (slug, data, position) values ('family-island', '{"slug":"family-island","name":"Острів для родини","type":"Кухонний острів","material":"Покостівський граніт (Grey Ukraine)","materialSlug":"grey-ukraine","location":"Луцьк","story":"У кухні приватного будинку острів збирає родину на сніданок, а світло-сірий граніт витримує щоденну роботу.","solution":"Компактний острів, матова поверхня, простий прямий торець.","image":"/proposals/family-island.webp","gallery":["/proposals/family-island.webp","/proposals/family-island.webp","/detail-stone-edge.webp"],"alt":"Сімейна кухня з островом із Покостівського граніту Grey Ukraine"}'::jsonb, 1) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_projects (slug, data, position) values ('bathroom-without-excess', '{"slug":"bathroom-without-excess","name":"Ванна без зайвого","type":"Ванна кімната","material":"Мармур Crema Marfil","materialSlug":"crema-marfil","location":"Тернопіль","story":"У стандартній ванній бежевий мармур зігріває тумбу та одну акцентну стіну, не перевантажуючи невелику кімнату.","solution":"Стільниця під раковину, одна стінова панель, захисне просочення.","image":"/proposals/bathroom-without-excess.webp","gallery":["/proposals/bathroom-without-excess.webp","/proposals/bathroom-without-excess.webp","/detail-stone-edge.webp"],"alt":"Звичайна ванна кімната з мармуром Crema Marfil"}'::jsonb, 2) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_projects (slug, data, position) values ('stairs-in-house', '{"slug":"stairs-in-house","name":"Сходи в будинку","type":"Сходи","material":"Покостівський граніт (Grey Ukraine)","materialSlug":"grey-ukraine","location":"Дубно","story":"Сходи у двоповерховому будинку мають пережити дітей і онуків, тому родина обрала міцний місцевий граніт.","solution":"Матові проступи, простий плінтус, протиковзна обробка.","image":"/proposals/stairs-in-house.webp","gallery":["/proposals/stairs-in-house.webp","/proposals/stairs-in-house.webp","/detail-stone-edge.webp"],"alt":"Світлі домашні сходи з проступами з Покостівського граніту Grey Ukraine"}'::jsonb, 3) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_projects (slug, data, position) values ('winterproof-entry', '{"slug":"winterproof-entry","name":"Вхід, який не боїться зими","type":"Вхідна група","material":"Габро (Kometa Black)","materialSlug":"kometa-black","location":"Костопіль","story":"Власникам будинку потрібні сходи, що не бояться снігу, солі та щоденного взуття. Термооброблене габро дає надійне зчеплення.","solution":"Термооброблені проступи, водовідвід, добре видимі краї.","image":"/proposals/winterproof-entry.webp","gallery":["/proposals/winterproof-entry.webp","/proposals/winterproof-entry.webp","/detail-stone-edge.webp"],"alt":"Доглянутий вхід до приватного будинку зі сходами з термообробленого габро Kometa Black"}'::jsonb, 4) on conflict (slug) do update set data = excluded.data;
