insert into public.stilnytsi_projects (slug, data, position) values ('windowsill-for-years', '{"slug":"windowsill-for-years","name":"Підвіконня на роки","type":"Підвіконня","material":"Caesarstone 4001 Fresh Concrete","materialSlug":"caesarstone-4001-fresh-concrete","location":"Івано-Франківськ","story":"Глибоке підвіконня у квартирі працює як полиця для вазонів і чашки, а кварц під бетон легко витирати.","solution":"Глибока плита, невеликий звис, акуратне примикання до вікна.","image":"/proposals/windowsill-for-years.webp","gallery":["/proposals/windowsill-for-years.webp","/proposals/windowsill-for-years.webp","/detail-stone-edge.webp"],"alt":"Затишне підвіконня для читання з кварцу Caesarstone 4001 Fresh Concrete"}'::jsonb, 6) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_projects (slug, data, position) values ('living-room-fireplace', '{"slug":"living-room-fireplace","name":"Камін у вітальні","type":"Камінний портал","material":"Мармур Nero Marquina","materialSlug":"nero-marquina","location":"Рівне","story":"Компактний чорний портал збирає сімейну вітальню з диваном і книжковими полицями, не забираючи всю стіну.","solution":"Лаконічна рамка, мінімальний шов, термічно відокремлений контур.","image":"/proposals/living-room-fireplace.webp","gallery":["/proposals/living-room-fireplace.webp","/proposals/living-room-fireplace.webp","/detail-stone-edge.webp"],"alt":"Сімейна вітальня з каміном із мармуру Nero Marquina"}'::jsonb, 7) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_projects (slug, data, position) values ('corner-coffee-shop', '{"slug":"corner-coffee-shop","name":"Кав’ярня на розі","type":"Барна стійка","material":"Лабрадорит (Volga Blue)","materialSlug":"volga-blue","location":"Чернівці","story":"Власник маленької кав’ярні обрав темний лабрадорит із синіми спалахами для короткої стійки біля кавомашини.","solution":"Міцний каркас, спокійна ділянка сляба, округлений зовнішній кут.","image":"/proposals/corner-coffee-shop.webp","gallery":["/proposals/corner-coffee-shop.webp","/proposals/corner-coffee-shop.webp","/detail-stone-edge.webp"],"alt":"Маленька місцева кав’ярня зі стійкою з лабрадориту Volga Blue"}'::jsonb, 8) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_projects (slug, data, position) values ('lviv-two-storey-stairs', '{"slug":"lviv-two-storey-stairs","name":"Сходи на другий поверх","type":"Сходи","material":"Покостівський граніт (Grey Ukraine)","materialSlug":"grey-ukraine","location":"Львів","story":"Сірий граніт обрано для сходів у двоповерховому будинку, де щодня ходять діти й домашній пес.","solution":"Матова протиковзна поверхня, простий плінтус, контрастний перший щабель.","image":"/proposals/lviv-two-storey-stairs.webp","gallery":["/proposals/lviv-two-storey-stairs.webp","/proposals/lviv-two-storey-stairs.webp","/detail-stone-edge.webp"],"alt":"Домашні сходи з Покостівського граніту Grey Ukraine"}'::jsonb, 9) on conflict (slug) do update set data = excluded.data;
