insert into public.stilnytsi_projects (slug, data, position) values ('khmelnytskyi-dining-table', '{"slug":"khmelnytskyi-dining-table","name":"Стіл для щоденних вечерь","type":"Обідній стіл","material":"Laminam Travertino","materialSlug":"laminam-travertino","location":"Хмельницький","story":"Тонка поверхня з рисунком травертину полегшує сімейну їдальню.","solution":"Стіл на шість місць із округленими кутами.","image":"/proposals/khmelnytskyi-dining-table.webp","gallery":["/proposals/khmelnytskyi-dining-table.webp","/proposals/khmelnytskyi-dining-table.webp","/detail-stone-edge.webp"],"alt":"Сімейний стіл із Laminam Travertino"}'::jsonb, 31) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('kvarc-chy-granit-stilnytsia', '{"slug":"kvarc-chy-granit-stilnytsia","title":"Кварц чи граніт для стільниці: що краще у 2026 році","h1":"Кварц чи граніт для кухонної стільниці — що обрати?","description":"Кварц чи граніт для стільниці? Порівнюємо міцність, догляд, тепло, рисунок і ціну, щоб обрати матеріал під вашу кухню.","dek":"Два найпопулярніші матеріали для кухні: де кожен виграє, а де програє.","category":"Матеріали","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Кварц і граніт закривають більшість запитів на кухонну стільницю, але роблять це по-різному. Граніт — природна порода з унікальним рисунком, яка спокійно переносить гарячий посуд і роками тримає полірування. Кварц — інженерний матеріал із кварцового піску та смоли: непористий, повторюваний за кольором і простіший у щоденному догляді. Нижче розбираємо різницю на прикладах із нашого виробництва в Костополі.","sections":[{"heading":"Що обрати — кварц чи граніт?","body":"Коротка відповідь: якщо ви багато готуєте, ставите гаряче прямо на стільницю і хочете, щоб кухня мала природний характер, обирайте граніт. Якщо для вас важливіші однорідний колір, повна відсутність пор і мінімум догляду, а гаряче ви звикли ставити на підставку, обирайте кварц.\n\nЦе не питання «краще або гірше», а питання сценарію. Обидва матеріали служать десятиліттями, обидва ріжуться, полірують і монтують за однаковою технологією. Різниця в поведінці під час експлуатації, і саме її варто зважити до замовлення."},{"heading":"Чим відрізняється кварцовий агломерат від граніту?","body":"Граніт видобувають блоками з родовища, розпилюють на сляби і полірують. Усе, що ви бачите на поверхні, створила природа: кристали польового шпату, кварцу і слюди, прожилки, вкраплення. Два сляби з одного блоку схожі, але не однакові.\n\nКварцовий агломерат виготовляють на заводі: приблизно 90–93 % меленого кварцу пресують зі смолою і пігментами під вакуумом. Звідси головні властивості: поверхня без пор, стабільний колір у межах партії, декори «під мармур» або «під бетон». Смола також визначає обмеження: матеріал не любить температури вище приблизно 150 °C і не призначений для вулиці, бо ультрафіолет з часом змінює відтінок."},{"heading":"Що міцніше і практичніше в побуті?","body":"За твердістю обидва матеріали близькі: 6–7 за шкалою Мооса, тобто ніж їх не подряпає. Різниця в іншому. На граніті можна забути гарячу сковороду і нічого не станеться. На кварці від гарячого дна лишається матовий слід, який не відполірувати вдома, тому підставка обов’язкова.\n\nКварц має перевагу біля мийки і в зоні готування: він не вбирає воду, олію, вино і буряковий сік. Граніт із якісним просоченням поводиться майже так само, але просочення потрібно періодично оновлювати. Сколи на кутах можливі в обох випадках, і в обох випадках їх реставрують на місці."},{"heading":"Що потребує менше догляду?","body":"Кварц: м’яка тканина, тепла вода, за потреби нейтральний засіб. Жодних просочень і воскування. Єдине правило — без абразивів і без агресивної хімії на кшталт засобів для духовок.\n\nГраніт: та сама щоденна рутина плюс перевірка просочення раз на кілька місяців. Тест простий: крапля води на поверхні; якщо за 10–15 хвилин під нею з’явилась темна пляма, час оновити захист. Ми показуємо, як це зробити, під час передачі виробу."},{"heading":"Кому підходить граніт, а кому кварц?","body":"Граніт для тих, хто цінує природний рисунок і не хоче думати про гаряче. Він доречний у будинках з великою кухнею, де стільниця працює як робочий стіл, і в інтер’єрах, де важлива фактура каменю.\n\nКварц для світлих кухонь у стилі мінімалізм, для довгих стільниць без видимих швів між однаковими плитами, для родин, які хочуть максимально просту експлуатацію. Він також зручний, коли колір потрібно точно узгодити з фасадами: у каталозі десятки повторюваних декорів Caesarstone, Vicostone і Silestone."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Пористість","Кварц непористий","Граніт потребує просочення раз на 1–3 роки"],["Гаряче","Кварц лише через підставку","Граніт переносить гарячий посуд"],["Рисунок","Кварц повторюваний","Граніт унікальний, погоджуйте сляб"],["Вулиця","Кварц не для екстер’єру","Граніт підходить для терас і ґанків"],["Ремонт","Обидва реставрують на місці","Полірування граніту відновлюється повністю"]]},"faq":[{"question":"Чи потрібно герметизувати граніт?","answer":"Так, полірований граніт просочують захисним складом після монтажу і повторюють процедуру за результатами водного тесту, зазвичай раз на один-три роки. Це займає пів години і не потребує майстра."},{"question":"Чи боїться кварц гарячого посуду?","answer":"Короткий контакт із теплою каструлею безпечний, але сковорода з плити або деко з духовки може лишити матовий слід через смолу в складі. Користуйтесь підставкою."},{"question":"Що дорожче?","answer":"Залежить від конкретного каменю. Українські граніти зазвичай доступніші за брендовий кварц, а імпортний граніт рідкісного кольору може коштувати дорожче. Порівняйте ваш розмір у калькуляторі."},{"question":"Що краще для родини з дітьми?","answer":"Обидва варіанти безпечні й гігієнічні. Кварц простіший, бо не має пор; граніт пробачає гаряче і випадкові удари. Для світлої кухні з активним готуванням частіше обирають кварц, для темної або природної кухні — граніт."}],"related":["/porivnyannya/kvarc-vs-granit","/vyroby/stilnytsi","/kalkulyator"],"materials":["grey-ukraine","caesarstone-5151-empira-white"],"categories":["stilnytsi"]}'::jsonb, 0) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('stilnytsia-z-kvarcytu-taj-mahal', '{"slug":"stilnytsia-z-kvarcytu-taj-mahal","title":"Стільниця з кварциту Taj Mahal: характеристики та догляд","h1":"Кварцит Taj Mahal для стільниці — що варто знати","description":"Кварцит Taj Mahal: природний рисунок, твердість, стійкість до тепла і плям, догляд. Як погодити сляб і розрахувати стільницю.","dek":"Світлий природний кварцит, який виглядає як мармур, а працює як граніт.","category":"Матеріали","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Taj Mahal — бразильський кварцит кремово-бежевого тону з м’якими золотавими прожилками. Його обирають замість мармуру, коли хочеться світлої природної поверхні без страху перед лимоном і вином. Це один із найтвердіших природних матеріалів у нашому каталозі, але з кількома нюансами, які варто знати до розкрою.","sections":[{"heading":"Що таке кварцит і чим він відрізняється від мармуру?","body":"Кварцит — метаморфічна порода, що утворилась із пісковику під тиском і температурою. Зерна кварцу зрослися в щільну масу, тому матеріал твердий, стійкий до подряпин і майже не реагує на кислоти. Зовні він часто нагадує мармур завдяки хвилястим прожилкам, і саме тому його плутають.\n\nМармур складається з кальциту. Кальцит м’який і розчиняється кислотами: крапля лимонного соку лишає на полірованому мармурі матову пляму за кілька хвилин. Кварцит у такій самій ситуації не змінюється. На дотик обидва камені холодні, але кварцит важче подряпати навіть ножем."},{"heading":"Чому Taj Mahal обирають замість мармуру?","body":"Головна причина — практичність без втрати вигляду. Світлий теплий тон і спокійний рисунок роблять кухню або острів схожими на мармуровий інтер’єр, але поверхня витримує щоденне готування. Матеріал добре поєднується з деревом, латунню і теплими фасадами.\n\nДруга причина — стабільність. Taj Mahal видобувають великими блоками, тому сляби мають розмір близько 3 × 1,8 м. Для довгих стільниць та островів це означає менше швів, а прожилки можна продовжити з горизонталі на торець при склеєній кромці 40 мм."},{"heading":"Наскільки він міцний і стійкий до плям?","body":"Твердість Taj Mahal — близько 7 за Моосом, це рівень граніту і вище. Гарячий посуд йому не шкодить, сколи на кутах трапляються рідко за умови правильного профілю кромки.\n\nЩодо плям: кварцит має мікропори, тому після монтажу ми обов’язково просочуємо поверхню. Без просочення олія або вино можуть лишити тінь, із просоченням поверхня поводиться як кварц. Важливо: не всі камені з назвою «кварцит» однакові. Деякі м’які різновиди містять кальцит і поводяться як мармур, тому ми перевіряємо кожен сляб кислотним тестом на краю плити до розкрою."},{"heading":"Як доглядати за кварцитом?","body":"Щодня: тепла вода, м’яка тканина, нейтральний засіб для каменю. Пролите прибирайте одразу, особливо кольорові рідини на світлій поверхні. Абразивні порошки та металеві губки не потрібні і шкідливі для полірування.\n\nРаз на пів року робіть водний тест. Якщо крапля вбирається за 10–15 хвилин, оновіть просочення: склад наносять губкою, витримують і витирають насухо. Матовий (honed) фініш просочують частіше, ніж полірований, бо його поверхня відкритіша."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Твердість","Кварцит близько 7 за Моосом","Мармур 3–4, дряпається ножем"],["Кислоти","Taj Mahal стійкий","Мармур втрачає полірування"],["Гаряче","Витримує посуд із плити","Мармур також, але швидше темніє"],["Догляд","Просочення раз на 1–2 роки","Мармур потребує делікатної хімії"],["Розмір сляба","Близько 3 × 1,8 м","Менше швів на довгій стільниці"]]},"faq":[{"question":"Кварцит натуральний чи штучний?","answer":"Натуральний. Його часто плутають зі штучним кварцом (агломератом), але кварцит видобувають із кар’єру блоками, а не виготовляють на заводі."},{"question":"Чи можна ставити гаряче?","answer":"Так. Кварцит витримує гарячий посуд без наслідків. Єдина обережність стосується різкого локального нагріву на місці склеєного шва, тому біля варильної панелі ми не робимо стиків."},{"question":"Чи темніє від води?","answer":"Не просочений кварцит може тимчасово темніти від води, як і граніт, і висихати без сліду. Після просочення вода лишається краплею на поверхні. Це і є тест на потребу в оновленні захисту."},{"question":"Чи підходить для острова?","answer":"Це один із найкращих варіантів для острова: великий формат сляба дозволяє зробити стільницю 2,5–3 м без швів, а склеєна кромка 40–60 мм дає масивний вигляд без зайвої ваги."}],"related":["/materialy/taj-mahal","/vyroby/stilnytsi","/blog/dogljad-za-marmurom-vanna","/kalkulyator"],"materials":["taj-mahal","bianco-carrara"],"categories":["stilnytsi"]}'::jsonb, 1) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('tovshchyna-stilnytsi-20-30-mm', '{"slug":"tovshchyna-stilnytsi-20-30-mm","title":"Товщина стільниці з каменю: 20 чи 30 мм?","h1":"Яку товщину стільниці обрати — 20 чи 30 мм?","description":"20 чи 30 мм для кам’яної стільниці: жорсткість, вага, звиси, вигляд торця і вартість. Коли достатньо 20 мм і як зробити товстий край.","dek":"Товщина як конструктивне й візуальне рішення для стільниці.","category":"Матеріали","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Більшість природного каменю в Україні продається слябами 20 і 30 мм, кварц — 20 і 30 мм, керамограніт — 6, 12 і 20 мм. Товщина визначає не лише вигляд торця, а й вагу, допустимі звиси, вимоги до каркаса кухні та ціну. Розповідаємо, як ми обираємо товщину на виробництві і коли «тонка» стільниця насправді краща.","sections":[{"heading":"Яка товщина оптимальна?","body":"Для кухонної стільниці на стандартних модулях глибиною 600 мм оптимальні 20 мм. Такої товщини достатньо для міцності, вирізів під мийку і варильну панель, а вага лишається помірною: близько 55 кг на погонний метр для граніту.\n\n30 мм обирають із двох причин: конструктивної (довгі звиси, сходи, зовнішні деталі, важкі мийки на широких прольотах) або візуальної (масивний торець без склеювання). Якщо потрібен лише вигляд, дешевше і легше зробити 20 мм зі склеєною кромкою до 40–60 мм."},{"heading":"Від чого залежить товщина стільниці?","body":"Від матеріалу, прольотів між опорами і того, що на стільниці стоятиме. Граніт і кварцит жорсткі, кварц гнучкіший і добре працює на 20 мм навіть із довгими звисами. Мармур м’якший, тому на широких прольотах ми даємо перевагу 30 мм або підсилюємо 20 мм алюмінієвим профілем знизу.\n\nВаріанти опор також важливі: суцільна поверхня модулів чи лише рамка, чи є барна консоль без ніжок, чи планується вбудована техніка з вирізом впритул до краю. Кожен виріз послаблює плиту, і біля нього перемичка має бути не вужчою за 50–70 мм."},{"heading":"Чим 20 мм відрізняється від 30 мм?","body":"Вага: 30 мм важчі в півтора раза. Для довгого острова це різниця в кількадесят кілограмів, яку має витримати каркас і яку треба підняти на поверх без ліфта.\n\nЗвиси: без підсилення 20 мм безпечно дають консоль близько 250–300 мм, 30 мм — до 350–400 мм. Для барних звисів більше цього потрібні сталеві пластини в пазах або кронштейни.\n\nВигляд: торець 30 мм читається як масивний, 20 мм як легкий і сучасний. Профіль кромки на 30 мм має більше варіантів: напівкруглий, огі, повний радіус."},{"heading":"Як товщина впливає на вигляд і вартість?","body":"Сляб 30 мм коштує дорожче, ніж 20 мм, а обробка кромки на товстій плиті довша. Для більшості кухонь різниця в підсумковому кошторисі становить від 20 до 40 %, тому ми пропонуємо 30 мм лише там, де це виправдано конструкцією.\n\nСклеєна кромка 40 мм із матеріалу 20 мм дає вигляд товстої плити за меншу ціну і вагу. Шов при правильному розкрої майже непомітний, особливо на однорідних матеріалах і кварці. На каменях із виразними прожилками ми підбираємо смужку з тієї самої зони сляба, щоб рисунок продовжувався."},{"heading":"Що врахувати для варильної панелі та мийки?","body":"Мийку нижнього монтажу ми підвішуємо до плити на кріплення, тому навколо вирізу лишаємо не менше 60 мм каменю до краю і закруглюємо кути радіусом 10–15 мм, щоб зняти напруження. Це правило однакове для 20 і 30 мм.\n\nВаріння панель: виріз має відступати від заднього краю на 50–70 мм, а між панеллю і мийкою потрібен суцільний фрагмент не менше 300 мм, інакше плиту доведеться ділити. Для індукції додатково перевіряємо глибину модуля під нею, щоб корпус не впирався в каркас."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Жорсткість","20 мм для кухні, 30 мм для сходів","Залежить від опор і породи"],["Вага","Близько 55 і 80 кг на пог. м граніту","Перевірити каркас і підйом"],["Звиси без опор","20 мм до 300 мм, 30 мм до 400 мм","Далі потрібне підсилення"],["Вигляд","Легкий або масивний торець","Склеєна кромка 40–60 мм"],["Вартість","30 мм на 20–40 % дорожче","Матеріал і обробка кромки"]]},"faq":[{"question":"Чи достатньо 20 мм для кухні?","answer":"Так, у переважній більшості кухонь 20 мм є стандартом: витримує мийку, варильну панель і щоденне навантаження. 30 мм потрібні для довгих консолей або масивного стилю."},{"question":"Як робиться товста кромка?","answer":"До нижньої частини плити 20 мм приклеюють смужку з того самого каменю, полірують торець і виходить край 40 мм. Шов проходить по нижній грані і з висоти очей не видно."},{"question":"Що краще для мінімалізму?","answer":"Для тонкого сучасного вигляду обирають 20 мм або керамограніт 12 мм із прямим торцем. Для «важкого» скандинавського або лофт-стилю — 30 мм або склеєні 60 мм."},{"question":"Чи можна нестандартну товщину?","answer":"Так: склеюванням двох або трьох шарів отримують кромку 60, 80 і навіть 100 мм. Товщина самої плити лишається 20 мм, тому вага не зростає пропорційно."}],"related":["/materialy/tovshchyny","/vyroby/stilnytsi/kraya","/vyroby/stilnytsi","/kalkulyator"],"materials":[],"categories":["stilnytsi"]}'::jsonb, 2) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('ukrainski-granity-porivnyannya', '{"slug":"ukrainski-granity-porivnyannya","title":"Українські граніти: порівняння видів та кольорів","h1":"Українські граніти — який обрати для вашого проєкту","description":"Огляд українських гранітів: Покостівський, Габро, Лабрадорит, Maple Red, Rosso Santiago та інші. Кольори, властивості, клас радіації, застосування.","dek":"Десять українських порід для інтер’єру, фасаду й ландшафту.","category":"Матеріали","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Україна має одні з найбільших у Європі запасів граніту, і більшість родовищ розташовані на Житомирщині, за кілька годин від нашого виробництва. Місцевий камінь дешевший за імпорт, не гірший за якістю і має документований клас радіації. Пояснюємо, чим відрізняються десять порід із нашого каталогу і де кожну доречно застосувати.","sections":[{"heading":"Який український граніт обрати?","body":"Для стільниці, сходів і будь-якої деталі, яку торкаються щодня, найчастіше обирають Покостівський граніт Grey Ukraine: спокійний світло-сірий тон, дрібне зерно, стабільна якість. Для контрастних чорних поверхонь — габро Kometa Black. Для акценту з кристалічним блиском — лабрадорит Volga Blue.\n\nЧервоні й рожеві породи (Maple Red, Rosso Santiago, Star of Ukraine, Flower of Ukraine, Leopard) працюють на фасадах, цоколях, сходах і в бруківці, де потрібен теплий колір і висока зносостійкість."},{"heading":"Чим відрізняються Покостівський, Габро та Лабрадорит?","body":"Покостівський граніт — класична гранітна порода: кварц, польовий шпат і слюда, світло-сіре дрібнозернисте тіло. Добре полірується, витримує термообробку, підходить для вулиці й інтер’єру. Найуніверсальніший камінь каталогу.\n\nГабро (Kometa Black) — темна магматична порода з дрібним зерном. Полірована поверхня майже чорна з тонкими сірими вкрапленнями. Термооброблене габро стає темно-сірим і матовим, чудово працює на вхідних сходах.\n\nЛабрадорит (Volga Blue, Irina Blue) — порода з великими кристалами, які дають синій або зелений спалах під кутом. Це декоративний камінь для стільниць, стійок і облицювання каміна. За твердістю не поступається граніту, але через великі кристали потребує обережного профілю кромки."},{"heading":"Які кольори доступні?","body":"Сірий: Grey Ukraine (Покостівське). Чорний: Kometa Black (габро). Чорно-синій: Volga Blue, Irina Blue. Червоні: Maple Red (Лезники), Rosso Santiago (Капустине), Carpazi (Токівське). Рожеві й коричнево-рожеві: Star of Ukraine (Дідковичі), Flower of Ukraine (Межиріч), Leopard (Корнин).\n\nВідтінок у межах одного родовища коливається від партії до партії, тому на виробництві ми показуємо фото і відео саме того сляба, який піде у ваш виріб, а великі фасадні партії підбираємо з одного блоку."},{"heading":"Що з класом радіації і де можна застосовувати?","body":"Кожен природний камінь містить сліди природних радіонуклідів. За ДСТУ будівельні матеріали ділять на класи: I клас (до 370 Бк/кг) дозволений для будь-якого застосування, включно з житлом; II клас (до 740 Бк/кг) — лише для дорожнього та промислового будівництва і зовнішніх робіт.\n\nБільшість гранітів нашого каталогу мають I клас і підтверджуються протоколом на партію. Токівський граніт Carpazi належить до II класу, тому ми продаємо його виключно для вулиці: бруківка, цоколі, підпірні стіни. Протокол на конкретну партію надаємо разом із рахунком."},{"heading":"Який граніт для інтер’єру, а який для екстер’єру?","body":"Інтер’єр: Grey Ukraine, Kometa Black, Volga Blue, Irina Blue, Maple Red, Rosso Santiago, Star of Ukraine — полірований або матовий фініш, стільниці, підвіконня, сходи, портали.\n\nЕкстер’єр: усі перелічені плюс Flower of Ukraine, Leopard і Carpazi. Для вулиці обирайте термооброблений або бучардований фініш: він не слизький у дощ і мороз, а колір стає спокійнішим на один-два тони світлішим за полірований."}],"table":{"headers":["Камінь","Колір","Де застосовувати"],"rows":[["Grey Ukraine","світло-сірий","Універсальний: інтер’єр та екстер’єр"],["Kometa Black","чорний","Стільниці, портали, вхідні сходи"],["Volga Blue / Irina Blue","чорно-синій із блиском","Стільниці, стійки, каміни"],["Maple Red / Rosso Santiago / Star of Ukraine","червоно-рожеві","Сходи, фасади, стільниці"],["Flower of Ukraine / Leopard","рожеві","Фасади, цоколі, бруківка"],["Carpazi","червоно-коричневий","Лише екстер’єр, II клас радіації"]]},"faq":[{"question":"Який граніт найтвердіший?","answer":"Габро і лабрадорит трохи щільніші за класичні граніти, але на практиці різниця не відчутна: усі породи каталогу мають твердість 6–7 за Моосом і міцність на стиск понад 180 МПа."},{"question":"Який колір найпопулярніший?","answer":"Для стільниць і сходів у приватних будинках — сірий Grey Ukraine, для акцентів — чорний Kometa Black. Червоні породи частіше беруть на фасади й бруківку."},{"question":"Чи безпечний граніт у домі?","answer":"Так, якщо це камінь I класу радіації з протоколом на партію. Ми не використовуємо в інтер’єрі матеріали II класу і надаємо документ на кожну поставку."},{"question":"Який граніт для фасаду?","answer":"Будь-який із каталогу за умови термообробленого або бучардованого фінішу і механічного кріплення. Найчастіше беруть Grey Ukraine за спокійний колір і Maple Red для контрастних цоколів."}],"related":["/materialy/granit","/materialy/labradoryt","/porivnyannya","/kalkulyator"],"materials":["grey-ukraine","kometa-black","volga-blue","maple-red","carpazi"],"categories":["stilnytsi","fasady","skhody"]}'::jsonb, 3) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('keramogranit-laminam-neolith-stilnytsia', '{"slug":"keramogranit-laminam-neolith-stilnytsia","title":"Стільниця з керамограніту Laminam/Neolith: плюси та мінуси","h1":"Керамограніт для стільниці — коли це найкращий вибір","description":"Керамограніт Laminam, Neolith, Dekton для стільниці: термостійкість, тонкість, UV-стабільність, ризик сколів і вимоги до монтажу.","dek":"Великоформатні тонкі плити у стільницях і фасадах.","category":"Матеріали","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Великоформатний керамограніт прийшов на кухні з фасадів: плита 1600 × 3200 мм товщиною 6–12 мм важить удвічі менше за камінь і не боїться нічого з того, що трапляється на кухні. Водночас це найвимогливіший до монтажу матеріал у нашому каталозі. Розбираємо, коли він виправданий, а коли краще взяти кварц або граніт.","sections":[{"heading":"Кому підходить керамограніт?","body":"Тим, кому потрібна поверхня, на яку можна ставити гаряче, різати без дошки і не думати про плями. Керамограніт спікається при температурі понад 1200 °C, тому не має смол і пор: ані сковорода, ані вино, ані ультрафіолет на нього не впливають.\n\nВін також підходить для довгих стільниць із мінімумом швів, для тонких «летючих» полиць і фасадів, де вага має значення. Плита 12 мм на кухні виглядає легкою і сучасною, а декори повторюють мармур, бетон або метал."},{"heading":"Які переваги великоформатних плит?","body":"Формат 3200 × 1600 мм закриває стільницю Г-подібної кухні з одним швом. Тонкий торець 12 мм або 20 мм дає графічний вигляд, а склеєна кромка «під кутом 45°» приховує білу основу плити.\n\nВага: 12-міліметрова плита важить близько 30 кг на м² проти 55–60 кг у граніту. Це полегшує монтаж на старі меблі, на стіни й у квартири без ліфта. Декор стабільний у межах партії, тому кухню можна доповнити через рік тією самою колекцією."},{"heading":"Які є недоліки і на що зважати?","body":"Крихкість на краях. Керамограніт тримає удар по площині, але сколюється від удару в ребро, особливо на прямій кромці. Тому ми рекомендуємо фаску або скруглення і не робимо гострих зовнішніх кутів.\n\nВимоги до основи. Плита 6 мм потребує суцільної опори по всій площі, 12 мм витримує рамку модулів, але біля вирізів все одно потрібні підкладки. Виріз під мийку і варильну панель ріжеться тільки на верстаті з водяним охолодженням, на об’єкті дорізати не можна.\n\nРемонт. Скол на керамограніті реставрується гірше, ніж на камені: полімерна вставка помітна на однорідних декорах. Тому обережність під час експлуатації важливіша, ніж із гранітом."},{"heading":"Чим Laminam і Neolith кращі за звичайну плитку?","body":"Звичайний керамограніт для підлоги — це плитка 600 × 600 мм товщиною 8–10 мм, розрахована на укладання на клей. Великоформатні плити Laminam, Neolith і Dekton виробляють на іншому обладнанні: вони мають рівну геометрію по всій довжині, повний прокрас у деяких колекціях і сертифікацію для контакту з харчовими продуктами.\n\nDekton технічно не керамограніт, а ультракомпактна поверхня зі спечених мінералів, але за властивостями і монтажем поводиться так само. Усі три бренди дають гарантію на матеріал за умови монтажу сертифікованим виробником, яким є і наша майстерня."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Гаряче","Керамограніт витримує повністю","Кварц лише через підставку"],["Товщина","6, 12 або 20 мм","Тонким плитам потрібна суцільна основа"],["Шви","Один шов на Г-кухню","Формат 3200 × 1600 мм"],["Краї","Ризик сколів на гострому ребрі","Фаска або скруглення"],["Вулиця","UV-стабільний","Підходить для літньої кухні й фасаду"]]},"faq":[{"question":"Чи можна ставити гаряче?","answer":"Так, без обмежень: матеріал не містить смол і не змінюється від температури, яку дає домашня кухня."},{"question":"Чи дряпається?","answer":"Поверхня твердіша за сталь ножа і не дряпається. Виняток — матові й структурні декори, на яких металевий посуд може лишати сірі сліди, які змиваються."},{"question":"Яка товщина?","answer":"Для стільниць беремо 12 мм із склеєною кромкою або 20 мм монолітно. 6 мм використовуємо для облицювання стін, фасадів меблів і фартухів."},{"question":"Чи підходить для фасаду й вулиці?","answer":"Так, це один із найкращих матеріалів для вентильованих фасадів і літніх кухонь: не вигорає, не вбирає воду, витримує мороз."}],"related":["/materialy/keramogranit","/vyroby/stilnytsi","/vyroby/fasady","/kalkulyator"],"materials":["laminam-calacatta","neolith-calacatta","dekton-kreta"],"categories":["stilnytsi","fasady"]}'::jsonb, 4) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('marmur-u-vanniy-kimnati', '{"slug":"marmur-u-vanniy-kimnati","title":"Мармур у ванній кімнаті: за і проти","h1":"Мармур у ванній — чи варто і як обрати","description":"Мармур у ванній: переваги, ризики, догляд і які сорти обрати. Bianco Carrara, Crema Marfil чи Nero Marquina — що краще для вологої зони.","dek":"Як спроєктувати вологу зону з природним мармуром.","category":"Матеріали","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Ванна кімната — найкраще місце для мармуру в домі. Тут немає гарячого посуду і ножів, а є вода, м’яке світло і бажання спокою, для якого цей камінь і створений. Проблеми з мармуром у ванній виникають не через матеріал, а через неправильний вузол, косметику з кислотами і засоби для чищення сантехніки. Розповідаємо, як цього уникнути.","sections":[{"heading":"Чи підходить мармур для ванної?","body":"Так, за трьох умов. Перша: поверхня просочена захисним складом, і його оновлюють раз на рік. Друга: усі шви на стільниці та біля стін загерметизовані, а на підлозі є ухил до трапа. Третя: у домі не використовують засоби з кислотою для очищення нальоту на камені.\n\nЗа цих умов мармурова стільниця під раковину, підвіконня або облицювання стіни служать десятиліттями. Італійські й іспанські ванни з мармуром сторічної давнини тому підтвердження."},{"heading":"Які переваги мармуру у ванній?","body":"Рисунок. Жоден інженерний матеріал не повторює глибину прожилок Carrara або теплоту Crema Marfil. Мармур дає відчуття спа навіть у маленькій кімнаті.\n\nПрохолода і гігієна. Полірований мармур легко витирається, не збирає пилу, а стільниця під накладну раковину виготовляється без швів на видимій площині.\n\nСумісність. Мармур поєднується з латунню, хромом, деревом і мікроцементом. Один камінь можна провести по стільниці, підвіконню і полиці в душі, і кімната стане цілісною."},{"heading":"Які ризики та як їх уникнути?","body":"Травлення кислотами. Лимон, оцет, засоби від вапняного нальоту і деяка косметика лишають на полірованому мармурі матові плями. Рішення: нейтральна хімія для каменю і матовий фініш, на якому сліди майже не видно.\n\nПлями від олій і барвників. Масла для тіла, фарба для волосся, крем можуть проникнути в пори. Рішення: просочення після монтажу і швидке витирання.\n\nВода в стиках. Проблема не мармуру, а швів. Рішення: епоксидний або силіконовий шов, гідроізоляція основи під плиткою, ухил на підлозі. Ми виготовляємо стільниці під раковину з бортиком або без нього, залежно від вузла."},{"heading":"Які сорти обрати — Bianco Carrara, Crema Marfil чи Nero Marquina?","body":"Bianco Carrara: світло-сірий фон із м’якими сірими прожилками. Найуніверсальніший, ховає воду і сліди, добре виглядає в матовому фініші. Підходить для стільниць і стін.\n\nCrema Marfil: кремово-бежевий, теплий, майже без контрасту. Робить кімнату візуально більшою, приховує вапняний наліт. Один із найпрактичніших мармурів для вологих зон.\n\nNero Marquina: чорний із білими прожилками. Дуже ефектний, але на ньому видно кожну краплю після висихання і сліди кислоти. Рекомендуємо для стін, полиць і акцентів, а для стільниці під раковину — лише при готовності витирати насухо."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Bianco Carrara","світлий із сірими жилами","Стільниці, стіни, матовий фініш"],["Crema Marfil","теплий бежевий","Найпрактичніший для вологої зони"],["Nero Marquina","темний контрастний","Помітні сліди води й кислот"],["Emperador Dark","темно-коричневий","Акцентні стіни, полиці"]]},"faq":[{"question":"Чи боїться мармур води?","answer":"Ні. Вода не руйнує мармур; шкодять кислоти й забруднення, що потрапляють у пори. Просочений камінь у ванній поводиться як будь-яка інша поверхня."},{"question":"Як часто герметизувати?","answer":"Раз на рік для стільниці й підлоги, раз на два роки для стін. Орієнтир — водний тест: якщо крапля вбирається за кілька хвилин, час оновити захист."},{"question":"Що робити з плямою від кислоти?","answer":"Матовий слід від кислоти — це не бруд, а протравлена поверхня. Дрібні сліди на матовому мармурі малопомітні; на полірованому їх прибирає майстер шліфуванням і поліруванням на місці."},{"question":"Чим замінити мармур?","answer":"Кварцитом Taj Mahal, якщо потрібен світлий природний камінь без чутливості до кислот, або кварцом чи керамогранітом із мармуровим декором, якщо важлива повна відсутність пор."}],"related":["/blog/dogljad-za-marmurom-vanna","/materialy/marmur","/vyroby/pidvikonnya","/kalkulyator"],"materials":["bianco-carrara","crema-marfil","nero-marquina"],"categories":["pidvikonnya","stilnytsi"]}'::jsonb, 5) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('yak-doglyadaty-za-granitnoyu-stilnytseyu', '{"slug":"yak-doglyadaty-za-granitnoyu-stilnytseyu","title":"Як доглядати за гранітною стільницею: правила та помилки","h1":"Догляд за гранітною стільницею — покрокові правила","description":"Догляд за гранітною стільницею: щоденне чищення, безпечні засоби, просочення, видалення плям від олії та вина, типові помилки.","dek":"Щоденний алгоритм без кислот, абразивів і випадкової хімії.","category":"Догляд","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Гранітна стільниця не потребує спеціального догляду, але потребує правильного. Більшість проблем, з якими до нас звертаються, це наслідки одного з трьох: агресивної хімії, забутого просочення або спроби відтерти пляму абразивом. Ось короткий регламент, який ми віддаємо клієнтам разом зі стільницею.","sections":[{"heading":"Як щодня чистити граніт?","body":"Тепла вода, м’яка тканина або губка, кілька крапель нейтрального мийного засобу. Протерли, змили чистою водою, витерли насухо, щоб не лишалось розводів на темному камені. Це вся щоденна рутина.\n\nРозливи прибирайте одразу, особливо олію, вино, каву і буряк. Граніт із просоченням не вбере їх за хвилину, але за ніч під калюжею олії може лишитись тінь. Не залишайте мокрі пакети та іржаві бляшанки на поверхні: іржа проникає в пори."},{"heading":"Які засоби можна, а які заборонені?","body":"Можна: засоби з написом «для природного каменю» або «pH-нейтральний», звичайний засіб для посуду в невеликій кількості, ізопропіловий спирт для знежирення перед просоченням.\n\nНе можна: оцет, лимонна кислота, засоби від вапняного нальоту, хлор і засоби для духовок, абразивні порошки, меламінові губки, металеві скребки. Кислоти і луги руйнують просочення і з часом матують полірування, абразиви лишають подряпини, які видно проти світла."},{"heading":"Чи потрібна герметизація і як часто?","body":"Так. Просочення (імпрегнат) заповнює мікропори і не дає рідинам проникати всередину. Ми наносимо його після монтажу, далі власник оновлює його самостійно.\n\nПеріодичність визначає водний тест, а не календар. Налийте столову ложку води на робочу зону біля мийки і зачекайте 15 хвилин. Якщо камінь під водою потемнів, просочення час оновити. Для полірованого граніту це зазвичай раз на один-три роки, для матового частіше.\n\nПроцедура: очистити й висушити поверхню, нанести імпрегнат губкою тонким шаром, витримати за інструкцією (зазвичай 10–20 хвилин), витерти залишки насухо. Надлишок, що висох на поверхні, дає плями, тому витирати треба ретельно."},{"heading":"Що робити з плямою від олії чи вина?","body":"Свіжа пляма: промокнути паперовим рушником, не розтираючи, і помити нейтральним засобом. У більшості випадків цього достатньо.\n\nЗастаріла жирова пляма: зробити пасту з харчової соди і води консистенції сметани, накласти на пляму шаром 5 мм, накрити плівкою і залишити на 12–24 години. Паста витягує олію з пор. Зняти, промити, за потреби повторити.\n\nОрганічна пляма (вино, кава, сік): та сама паста, але з 3 % перекисом водню замість води. На темному граніті спершу перевірте на непомітній ділянці. Іржу і невідомі плями краще показати нам: фото загального плану і крупний план достатньо для поради."},{"heading":"Чого ніколи не можна робити?","body":"Не різати на камені без дошки: граніт не постраждає, а ножі затупляться за тиждень. Не ставати на стільницю і не сідати на звис: плита розрахована на розподілене навантаження, а не на точкове 80 кг на краю.\n\nНе ставити гарячу сковороду на шов між плитами і на місце вирізу біля варильної панелі: локальний перегрів клейового шва може його послабити. Сам граніт гарячого не боїться. Не використовувати воски й «поліролі» з побутової хімії: вони дають липку плівку, яка збирає бруд і не має нічого спільного з поліруванням каменю."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Щоденне очищення","Можна","М’яка тканина, нейтральний засіб, витерти насухо"],["Кислоти й абразиви","Не можна","Матують полірування, руйнують просочення"],["Гаряче","Можна","Уникати лише швів і країв вирізів"],["Просочення","Раз на 1–3 роки","Періодичність визначає водний тест"],["Плями","Паста із соди","Не терти абразивом"]]},"faq":[{"question":"Чи можна різати на граніті?","answer":"Камінь від ножа не постраждає, але ніж швидко затупиться. Використовуйте дошку, це зручніше для обох."},{"question":"Чи можна ставити гаряче?","answer":"Так, граніт витримує посуд із плити й духовки. Єдине місце, де краще підкласти підставку, це клейовий шов між плитами."},{"question":"Чим прибрати жир?","answer":"Свіжий — засобом для посуду. Застарілий — пастою із соди й води на добу під плівкою. Знежирювачі для кухні з лугом використовувати не варто."},{"question":"Як повернути блиск?","answer":"Якщо поверхня стала тьмяною через засоби з воском або кислотою, спершу помийте її нейтральним засобом і спиртом. Якщо полірування справді пошкоджене, його відновлює майстер на місці машинкою з алмазними пастами."}],"related":["/dohliad","/vyroby/stilnytsi","/materialy/granit","/kalkulyator"],"materials":["grey-ukraine","kometa-black"],"categories":["stilnytsi"]}'::jsonb, 6) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('dogljad-za-marmurom-vanna', '{"slug":"dogljad-za-marmurom-vanna","title":"Догляд за мармуром: як чистити та виводити плями","h1":"Як доглядати за мармуром і виводити плями","description":"Догляд за мармуром: безпечні засоби, що руйнує камінь, як вивести органічні, жирові та іржаві плями, як часто просочувати.","dek":"Безпечний догляд за кальцитовою поверхнею без кислот.","category":"Догляд","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Мармур складається з кальциту, а кальцит розчиняється кислотами. Це єдине, що потрібно пам’ятати, і з цього випливає весь догляд: жодних кислотних засобів, швидке витирання, регулярне просочення. Решта не складніша за догляд за будь-якою іншою поверхнею.","sections":[{"heading":"Як безпечно чистити мармур?","body":"Щодня: тепла вода і м’яка тканина. Раз на тиждень: нейтральний засіб для каменю, розведений за інструкцією, потім чиста вода і суха тканина. На полірованому мармурі важливо витирати насухо, інакше після висихання лишаються сліди від крапель, особливо на темних сортах.\n\nДля ванної тримайте окрему пляшку засобу для каменю і не використовуйте на стільниці те, чим миєте унітаз чи змішувач. Більшість засобів для сантехніки містить кислоту проти вапняного нальоту."},{"heading":"Які засоби руйнують мармур?","body":"Кислоти: оцет, лимон, засоби від накипу і нальоту, деякі засоби для скла і плитки. Вони не бруднять, а травлять: за кілька хвилин на полірованій поверхні з’являється матова пляма форми краплі.\n\nЛуги й хлор: відбілювачі та засоби для духовок роз’їдають просочення і знебарвлюють кольоровий мармур. Абразиви: порошки, меламінові губки, жорсткі щітки дряпають кальцит, який м’якший за пісок.\n\nКосметика: олії для тіла, фарба для волосся, деякі парфуми на спирту з барвниками. Ставте флакони на підставку і витирайте краплі одразу."},{"heading":"Як вивести органічні, жирові та іржаві плями?","body":"Спершу визначте тип. Матова пляма без кольору — це травлення кислотою, її не миють, а полірують. Кольорова пляма в порах — це забруднення, яке витягують компресом.\n\nОрганічні (кава, чай, вино, косметика): паста з білого паперового рушника або крохмалю, змочена 3 % перекисом водню, під плівкою на 12–24 години. Жирові (олія, крем): паста із соди й води, той самий час. Іржа: тільки спеціальні пасти для мармуру без кислоти; побутові засоби від іржі містять кислоту і зіпсують камінь.\n\nПісля компресу поверхню промивають, висушують і за потреби повторюють. Просочення після виведення плями оновлюють обов’язково."},{"heading":"Як часто просочувати мармур?","body":"У ванній раз на рік для стільниці й підлоги, раз на два роки для стін. На кухонному підвіконні або столі — раз на рік. Тест той самий, що для граніту: крапля води, 10 хвилин, темна пляма означає, що час.\n\nВажливо розуміти, що просочення захищає від плям, але не від кислот. Матовий (honed) фініш допомагає ще й проти травлення: на ньому сліди кислоти майже не видно, і для активної ванної ми радимо саме його."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Органічна пляма","Компрес із перекисом","Спершу тест на непомітній ділянці"],["Жирова","Паста із соди","Не розтирати, дати компресу час"],["Іржа","Паста для мармуру без кислоти","Побутові засоби від іржі заборонені"],["Кислотне травлення","Полірування майстром","Не миється, це зміна поверхні"]]},"faq":[{"question":"Чи можна оцет або лимон?","answer":"Ні. Обидва протравлюють кальцит за хвилини. Наліт на мармурі прибирають нейтральними засобами для каменю або м’якою пастою із соди."},{"question":"Чим прибрати каву чи вино?","answer":"Свіже — водою і тканиною. Те, що встигло вбратись, компресом із 3 % перекисом водню на 12–24 години під плівкою."},{"question":"Як повернути блиск?","answer":"Побутові «поліролі» не допоможуть. Тьмяну від кислот поверхню відновлює майстер: шліфування, полірування і нове просочення на місці за кілька годин."},{"question":"Чи потрібна щорічна обробка?","answer":"Так, просочення раз на рік для стільниць і підлоги у вологих зонах. Це 20 хвилин роботи губкою і найдешевший спосіб продовжити життя мармуру."}],"related":["/dohliad","/blog/marmur-u-vanniy-kimnati","/materialy/marmur","/kalkulyator"],"materials":["bianco-carrara","crema-marfil"],"categories":["pidvikonnya"]}'::jsonb, 7) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('pidvikonnya-z-kamenyu-marmur-granit', '{"slug":"pidvikonnya-z-kamenyu-marmur-granit","title":"Підвіконня з каменю: мармур чи граніт?","h1":"Кам’яне підвіконня — мармур чи граніт?","description":"Підвіконня з каменю: мармур чи граніт, товщина, звис, монтаж і догляд. Що обрати для сонячної сторони, вазонів і вологи.","dek":"Вибір породи для сонця, вологи, рослин і щоденного користування.","category":"Проєктування","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Підвіконня — найпростіший спосіб додати в дім природний камінь: одна плита, один день монтажу і десятиліття без заміни. Питання лише в породі. Граніт витримує вазони, воду й сонце без нагадувань про догляд; мармур виглядає м’якше і теплішим, але просить уваги. Пояснюємо, як обираємо ми.","sections":[{"heading":"Що обрати для підвіконня?","body":"Для кухні, дитячої та підвіконь із рослинами обирайте граніт: Grey Ukraine, Kometa Black або кварц, якщо потрібен світлий однорідний колір. Для спальні, вітальні й ванної, де підвіконня працює як полиця, а не робоча поверхня, доречний мармур Crema Marfil або Bianco Carrara.\n\nЯкщо вікна виходять на південь і на підвіконні стоятимуть темні предмети, врахуйте нагрівання: темний граніт на сонці стає гарячим, світлий мармур і кварц лишаються прохолодними. Кварц при цьому не ставте під прямим сонцем протягом усього дня: смола з роками може змінити відтінок."},{"heading":"Чим граніт кращий за мармур для підвіконня?","body":"Граніт не боїться води з-під вазонів, кислоти з добрив, слідів від чашок і кігтів кота. Просочення оновлюють раз на кілька років, а не щороку. Він твердіший, тому край не сколюється від удару рамою вікна або мийкою при прибиранні.\n\nМармур виграє в іншому: він приємніший на дотик, дає світлий теплий тон, який граніту недоступний, і виглядає доречно в класичних інтер’єрах. Якщо вазони стоять на підставках, а підвіконня не заливають, мармур служить не менше."},{"heading":"Які переваги каменю над пластиком і деревом?","body":"Камінь не жовтіє, не деформується від батареї знизу і сонця зверху, не вбирає запахи і не дряпається так, як ПВХ. Він важчий, і в цьому його перевага: плита лежить на розчині і не «грає», а глибоке підвіконня 400–600 мм витримує людину, яка сіла на нього з книгою.\n\nДерево красиве, але потребує лаку і боїться води під вазонами. Камінь ставлять один раз і зазвичай на весь строк служби вікна, а при заміні вікна плиту переставляють."},{"heading":"Як відбувається виготовлення й установка?","body":"Замір після встановлення вікна і штукатурки укосів: фіксуємо довжину, глибину, звис, форму країв і те, чи заходить плита в укоси. Стандартний звис 30–50 мм від стіни, товщина 20 мм, для глибоких підвіконь понад 500 мм або довжини понад 2 м беремо 30 мм.\n\nМонтаж: плиту укладають на цементний розчин або монтажну піну по вирівняній основі з невеликим нахилом до кімнати, не більше 1–2 мм, щоб вода з вікна не збиралась біля рами. Між плитою і рамою лишають зазор 3–5 мм під герметик, під плитою ставлять підкладки, щоб не порушувати вентиляцію батареї. Роботи займають день, користуватись можна наступного дня."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Міцність","Граніт 6–7 за Моосом","Мармур 3–4, м’якший"],["Волога й добрива","Граніт практичніший","Мармур потребує просочення й підставок"],["Сонце","Темний граніт нагрівається","Кварц не для прямого сонця"],["Вигляд","Контрастний або нейтральний","Мармур теплий і пластичний"],["Товщина","20 мм стандарт","30 мм для довжини понад 2 м"]]},"faq":[{"question":"Що довговічніше?","answer":"Граніт: він твердіший і не реагує на кислоти. Мармур служить так само довго, якщо його просочують і не заливають."},{"question":"Чи боїться сонця або вологи?","answer":"Граніт і мармур не бояться сонця. Кварц під прямими променями цілий день може змінити відтінок за роки. Вологи не боїться жоден із каменів, шкодять лише забруднення в порах."},{"question":"Яка товщина?","answer":"Стандарт 20 мм. Для довгих підвіконь понад 2 м, глибоких понад 500 мм або з великим звисом беремо 30 мм."},{"question":"Чи можна нестандартну форму?","answer":"Так: заокруглені кути, вирізи під укоси, еркерне підвіконня з кількох плит, підвіконня-стільниця, що переходить у робочу зону кухні."}],"related":["/vyroby/pidvikonnya","/materialy","/dostavka-i-montazh","/kalkulyator"],"materials":["grey-ukraine","crema-marfil"],"categories":["pidvikonnya"]}'::jsonb, 8) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('shody-z-granitu-cina-vygotovlennya', '{"slug":"shody-z-granitu-cina-vygotovlennya","title":"Сходи з граніту: виготовлення, обробка, вартість","h1":"Гранітні сходи — як обираються та виготовляються","description":"Гранітні сходи: накладні й цільні, фініш для вулиці й інтер’єру, протиковзкість, розміри сходинок і з чого складається вартість.","dek":"Конструкція, фініш і безпечний вузол для інтер’єру та вулиці.","category":"Проєктування","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Гранітні сходи це найдовговічніша частина будинку: ґанки з українського граніту стоять по 50 років без ремонту. Але саме на сходах помилки коштують найдорожче, бо слизька сходинка або невідведена вода відчуваються щодня. Розповідаємо, як ми проєктуємо сходи для будинків, під’їздів і магазинів.","sections":[{"heading":"Які бувають гранітні сходи?","body":"За конструкцією: накладні (проступі й підсходинки з плит 20–30 мм на бетонній основі) і цільні (масивні блоки 100–150 мм, які самі є сходинками). Накладні використовують у 90 % випадків: і в будинках, і на вулиці.\n\nЗа місцем: інтер’єрні (полірований або матовий фініш, дерев’яні або кам’яні підсходинки, плінтус уздовж стіни) і зовнішні (термооброблений фініш, ухил для води, крапельник під проступом, морозостійкий клей)."},{"heading":"Накладні чи цільні — у чому різниця?","body":"Накладні сходи легші, дешевші й дозволяють будь-який фініш. Проступ 30 мм із крапельником і підсходинка 20 мм кладуться на бетонний марш на клей для каменю. Із них роблять і прямі, і забіжні, і гвинтові марші.\n\nЦільні блоки доречні для ландшафту і масивних входів: підпірні сходи в саду, ґанок у стилі «камінь із кар’єру». Вони не потребують бетонної основи в класичному розумінні, але потребують важкої техніки для монтажу і коштують суттєво дорожче через обсяг матеріалу."},{"heading":"Яка обробка потрібна для вулиці?","body":"Для зовнішніх сходів полірування небезпечне: у дощ і мороз воно перетворюється на ковзанку. Ми використовуємо термообробку (поверхню обпалюють, кристали лускають і дають шорстку фактуру) або бучардування (механічне точкування). Обидва фініші протиковзкі навіть мокрими.\n\nКомпромісний варіант для інтер’єру, де хочеться блиску: полірований проступ із термообробленими або піскоструминними смугами шириною 30–40 мм біля краю. Вони працюють як протиковзка стрічка і не псують вигляду. Для вулиці також важливий ухил проступа 1–2 % від будинку і крапельник знизу, щоб вода не текла на підсходинку і не замерзала в шві."},{"heading":"Від чого залежить вартість?","body":"Матеріал: український граніт Grey Ukraine доступніший за габро і лабрадорит, імпорт коштує ще дорожче. Товщина: проступ 30 мм проти 20 мм, масивні блоки окремо.\n\nГеометрія: прямі сходинки стандартної ширини 300–330 мм дешевші за забіжні й радіусні, кожен виріз під поручень або нестандартний кут додає роботи. Фініш: полірування базове, термообробка і бучардування дорожчі. Плюс доставка й монтаж, який на сходах займає більше часу, ніж на стільниці, бо кожна деталь підганяється на місці.\n\nОрієнтир на ваш марш можна отримати в калькуляторі, точний кошторис після заміру бетонної основи."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Полірування","Інтер’єр, вертикалі, деталі","Слизьке мокрим, додайте смуги"],["Шліфування (матовий)","Інтер’єр, спокійна поверхня","Менш слизьке, легше в догляді"],["Термообробка","Вулиця, ґанки, тераси","Протиковзка шорстка фактура"],["Бучардування","Вулиця, громадські входи","Найгрубіша фактура, пандуси"]]},"faq":[{"question":"Чи слизькі гранітні сходи?","answer":"Поліровані — так, особливо мокрі. Термооброблені й бучардовані — ні, вони протиковзкі навіть у дощ і в мороз. Для інтер’єру можна поєднати блиск із протиковзкими смугами."},{"question":"Яка максимальна довжина сходинки?","answer":"Із плити 30 мм робимо цільні проступи до 3 м, обмеження — розмір сляба. Довші сходинки складають із двох плит зі швом по центру або над опорою."},{"question":"Що обрати для ґанку?","answer":"Термооброблений Grey Ukraine або Kometa Black товщиною 30 мм із крапельником. Це найпоширеніше і найнадійніше рішення для українського клімату."},{"question":"Скільки коштує?","answer":"Залежить від породи, товщини, кількості й форми сходинок, фінішу і монтажу. Введіть розміри у калькулятор для орієнтира, точну суму дамо після заміру."}],"related":["/vyroby/skhody","/materialy/granit","/dostavka-i-montazh","/kalkulyator"],"materials":["grey-ukraine","kometa-black"],"categories":["skhody"]}'::jsonb, 9) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('fasad-z-kamenyu-yakyy-kamin', '{"slug":"fasad-z-kamenyu-yakyy-kamin","title":"Фасад з каменю: який камінь обрати для облицювання","h1":"Облицювання фасаду каменем — який камінь обрати","description":"Фасад із каменю: граніт, травертин, кварцит чи керамограніт. Товщина плит, вентильований фасад і механічне кріплення, шви, догляд.","dek":"Матеріал, підсистема, шви та вода у довговічному фасаді.","category":"Проєктування","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Кам’яний фасад це не «плитка, приклеєна до стіни», а інженерна система: підконструкція, анкери, плити, шви й водовідведення. Матеріал у ній важливий, але не єдиний. Пояснюємо, який камінь ми рекомендуємо для української зими, як він кріпиться і чому граніт майже завжди виграє.","sections":[{"heading":"Який камінь найкращий для фасаду?","body":"Для приватного будинку й комерційної будівлі в нашому кліматі це граніт: він морозостійкий (витримує понад 300 циклів замерзання), не вбирає воду і не вигорає. Травертин і пісковик красиві, але пористі й потребують захисту і регулярного догляду. Мармур на фасаді швидко втрачає полірування від дощу з кислотами міста.\n\nАльтернатива каменю — великоформатний керамограніт Laminam або Neolith: тонкий, легкий, UV-стабільний, у декорах під камінь або бетон. Він добре працює на вентильованих фасадах, де вага має значення."},{"heading":"Чому граніт — практичний вибір?","body":"Граніт не потребує просочення на фасаді: вода з нього стікає, а бруд змивається дощем. Термооброблена поверхня ховає дрібні відмінності партій і не дає відблисків. Український граніт доступний великими партіями з одного блоку, тож колір по всьому фасаду однорідний.\n\nЩе одна перевага в ремонтопридатності: пошкоджену плиту на механічному кріпленні замінюють за годину без демонтажу сусідніх. Для цоколя граніт взагалі без альтернатив: сіль, бризки, лопата двірника й удари не лишають на ньому сліду."},{"heading":"Як кріпляться фасадні плити?","body":"Мокрий спосіб (на клей до стіни) допустимий для цоколів і невеликих ділянок висотою до 3 м із плитами товщиною 20 мм. Вище цього фасад роблять вентильованим: до стіни кріплять кронштейни й напрямні, у них — клямери або штифти, які тримають плити 30 мм у пропилах на торцях.\n\nМіж плитами лишають шов 4–6 мм для температурних рухів, за плитами — вентиляційний зазор 30–50 мм і утеплювач. Так стіна не намокає, конденсат виводиться, а камінь не тріскається від морозу. Розрахунок підсистеми робить конструктор, ми виготовляємо плити з пропилами під конкретне кріплення."},{"heading":"Чи потрібен догляд за кам’яним фасадом?","body":"Граніт: мийка водою під тиском раз на кілька років, перевірка швів і кріплень. Просочення не потрібне. Травертин і вапняк: гідрофобізатор раз на 3–5 років, інакше пори збирають бруд і мох на північній стороні.\n\nЦоколь із будь-якого каменю варто раз на рік мити від солі після зими. Керамограніт не потребує нічого, крім мийки. Якщо фасад зроблено правильно, догляд зводиться до ополіскування, а сама конструкція служить довше за будинок."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Граніт","Морозостійкий, не вбирає воду","Механічне кріплення від 3 м"],["Травертин","Тепла пориста фактура","Гідрофобізатор, захист від бруду"],["Кварцит","Виразний рисунок","Перевіряти партію, ціна вища"],["Керамограніт","Легкий, UV-стабільний","Вентфасад, тонкі плити 6–12 мм"]]},"faq":[{"question":"Який камінь для суворого клімату?","answer":"Граніт із термообробленим фінішем на вентильованому фасаді. Він не боїться морозу, води й солі та не потребує просочення."},{"question":"Яка товщина плит?","answer":"20 мм для клейового кріплення на цоколь, 30 мм для вентильованого фасаду на клямерах. Керамограніт 6–12 мм на власній підсистемі."},{"question":"Чи вигорає граніт?","answer":"Ні. Мінерали граніту стабільні до ультрафіолету, колір через 30 років той самий. Змінитись може лише полірування, тому для фасаду беруть матовий або термооброблений фініш."},{"question":"Як доглядати?","answer":"Мийка водою під тиском раз на кілька років і огляд швів. Для пористих каменів додатково гідрофобізатор раз на 3–5 років."}],"related":["/vyroby/fasady","/materialy/granit","/materialy/keramogranit","/kalkulyator"],"materials":["grey-ukraine","maple-red","neolith-iron-corten"],"categories":["fasady"]}'::jsonb, 10) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('granitna-chy-vibropresovana-brukivka', '{"slug":"granitna-chy-vibropresovana-brukivka","title":"Гранітна чи вібропресована бруківка: що краще","h1":"Гранітна чи вібропресована бруківка — що обрати","description":"Гранітна чи вібропресована бруківка: міцність, довговічність, вигляд, ремонт і вартість за життєвий цикл. Що обрати для двору, доріжок і заїзду.","dek":"Матеріал мощення для двору, доріжок і заїзду автомобіля.","category":"Проєктування","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Бетонна вібропресована бруківка дешевша на старті, гранітна дешевша за 20 років. Це головна теза, і решта статті пояснює, чому так і в яких випадках бетон усе-таки виправданий. Ми виготовляємо гранітну бруківку з українського каменю і бачимо обидва матеріали на об’єктах щодня.","sections":[{"heading":"Що обрати для двору?","body":"Для заїзду, під’їзної доріжки і паркомісця обирайте граніт: колота або пиляно-колота бруківка 100 × 100 × 50–100 мм витримує вагу авто і зиму з сіллю без змін. Для садових доріжок, де ходять лише люди, підходять обидва матеріали, і тут вирішує бюджет і вигляд.\n\nЯкщо двір великий, поширений компроміс: граніт на заїзді, вході й уздовж фасаду, бетон у господарській зоні. Так найпомітніші ділянки отримують матеріал на весь термін життя будинку."},{"heading":"Чим гранітна бруківка міцніша?","body":"Граніт це монолітний природний камінь із міцністю на стиск 180–220 МПа. Бетонна бруківка має міцність 40–60 МПа і складається з цементного каменю з наповнювачем. Під колесами і в мороз бетон із часом кришиться по краях і втрачає верхній шар із пігментом, граніт не змінюється.\n\nВодопоглинання граніту нижче 0,2 %, тому вода не проникає в камінь і не рве його при замерзанні. У бетону воно 4–6 %. Через 10–15 зим різниця видна неозброєним оком: гранітна бруківка виглядає як щойно покладена, бетонна потребує заміни."},{"heading":"Коли вібропресована бруківка виправдана?","body":"Коли бюджет обмежений, а ділянка велика і не має важкого транспорту. Коли потрібна точна повторювана геометрія і колір для геометричного малюнка. Коли покриття тимчасове або через кілька років планується перепланування двору.\n\nЯкісний бетон від великого виробника з товщиною 60–80 мм і правильною основою служить 10–15 років і виглядає охайно. Проблеми починаються з дешевої бруківки сумнівних заводів: вона втрачає колір за два сезони і лущиться."},{"heading":"Що з вартістю за квадратний метр?","body":"Матеріал: гранітна бруківка дорожча за бетонну в кілька разів. Укладання: приблизно однакове для обох, бо основа й робота ті самі. Життєвий цикл: граніт кладуть один раз, бетон переукладають раз на 10–15 років разом із роботою й вивезенням старого.\n\nЄ й непряма економія: гранітну бруківку після демонтажу (наприклад, при ремонті комунікацій) кладуть назад, бетонну зазвичай викидають. Орієнтир для вашої площі можна порахувати в калькуляторі бруківки."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Міцність","Граніт 180–220 МПа","Бетон 40–60 МПа"],["Водопоглинання","Граніт до 0,2 %","Бетон 4–6 %, лущиться в мороз"],["Вигляд через 15 років","Граніт без змін","Бетон вицвітає, кришиться"],["Ремонт","Граніт перекладають повторно","Бетон замінюють новим"],["Стартова ціна","Граніт дорожчий","Бетон дешевший"]]},"faq":[{"question":"Що довговічніше?","answer":"Граніт: строк служби вимірюється десятиліттями без зміни вигляду. Бетонна бруківка розрахована на 10–15 років у нашому кліматі."},{"question":"Що дешевше?","answer":"На старті — бетон. За життєвий цикл із переукладанням — граніт, бо його кладуть один раз."},{"question":"Що для заїзду авто?","answer":"Гранітна бруківка 80–100 мм на щебеневій основі. Бетон витримує легкові авто, але краї швидко кришаться від маневрів."},{"question":"Що для пішохідних доріжок?","answer":"Обидва матеріали. Граніт 50–60 мм або бетон 60 мм на піщано-щебеневій основі; вибір за виглядом і бюджетом."}],"related":["/vyroby/brukivka","/blog/ukladannya-granitnoyi-brukivky","/porivnyannya","/kalkulyator"],"materials":["grey-ukraine","maple-red","flower-of-ukraine"],"categories":["brukivka"]}'::jsonb, 11) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('ukladannya-granitnoyi-brukivky', '{"slug":"ukladannya-granitnoyi-brukivky","title":"Укладання гранітної бруківки: технологія та основа","h1":"Як укладають гранітну бруківку — етапи й основа","description":"Укладання гранітної бруківки: шари основи для доріжки і заїзду, ухили, бордюри, способи мощення, заповнення швів і догляд після укладання.","dek":"Основа, ухили, шви та порядок робіт для стабільного мощення.","category":"Проєктування","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Гранітна бруківка служить вічно, а от основа під нею ні, якщо її зробити неправильно. Просілі колії на заїзді й «хвилі» на доріжці це завжди помилка в шарах, ущільненні або воді, а не в камені. Описуємо технологію, за якою працюємо ми, і пояснюємо, чим відрізняється основа для пішоходів і для автомобіля.","sections":[{"heading":"Як правильно укласти бруківку?","body":"Послідовність одна для всіх ділянок: розмітка й планування ухилів, виїмка ґрунту на глибину всіх шарів, геотекстиль, щебінь із пошаровим ущільненням, бордюри на бетон, вирівнювальний шар, укладання каменю, трамбування, заповнення швів.\n\nУхил покриття від будинку не менше 1,5–2 %, тобто 2 см на метр. Вода має йти до газону, дренажного лотка або зливоприймача, а не до стіни. Це правило важливіше за товщину каменю."},{"heading":"Яку основу підготувати?","body":"Пішохідна доріжка: виїмка 25–30 см, геотекстиль, щебінь фракції 20–40 шаром 15 см з ущільненням віброплитою, вирівнювальний шар із гранітного відсіву або суміші піску з цементом 3–5 см, бруківка 50–60 мм.\n\nЗаїзд і паркомісце: виїмка 40–45 см, геотекстиль, щебінь 40–70 шаром 15 см, щебінь 20–40 шаром 10 см, кожен шар ущільнюють окремо, вирівнювальний шар 3–4 см, бруківка 80–100 мм. На слабких ґрунтах додають шар піску 10 см під щебінь або армовану бетонну плиту.\n\nБордюри ставлять на бетонну подушку до укладання каменю: вони тримають полотно від розповзання. Без бордюрів або з бордюрами «на пісок» краї сідають за перший сезон."},{"heading":"Які є способи мощення й візерунки?","body":"Рядами: найпростіший і найшвидший, підходить для доріжок. Зі зміщенням на пів каменю: міцніший, бо шви не збігаються, стандарт для заїздів. Дугами й віялом: класика європейських площ із колотої бруківки 100 × 100 мм, потребує досвіду і більшої кількості каменю, зате чудово тримає навантаження.\n\nДля контрастних малюнків поєднують сірий Grey Ukraine із червоним Maple Red або чорним габро: облямівка, смуги, шаховий модуль. Пиляно-колота бруківка з рівним верхом зручніша для ходьби на підборах і велосипеда, повністю колота фактурніша і краще працює на ухилах."},{"heading":"Як доглядати після укладання?","body":"Перші два тижні шви досипають: відсів або пісок осідають після дощів, і їх потрібно довести до рівня каменю. Далі раз на рік підмітають, за потреби досипають шви і промивають водою. Полімерний пісок для швів тримається краще звичайного і не проростає травою, але дорожчий.\n\nВзимку прибирайте сніг пластиковою або гумовою лопатою, сіль граніту не шкодить. Мох на північній тіньовій стороні змивається водою під тиском раз на кілька років. Якщо один камінь просів або пошкоджений, його виймають, підсипають основу і кладуть назад: це головна перевага мощення перед асфальтом і бетоном."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Пісок","Вирівнювальний шар 3–5 см","Тільки поверх ущільненого щебеню"],["Щебінь","Несучий шар 15–25 см","Пошарове ущільнення віброплитою"],["Бетон","Бордюри, слабкі ґрунти, лотки","Дренаж і деформаційні шви"],["Геотекстиль","Між ґрунтом і щебенем","Не дає шарам змішуватись"]]},"faq":[{"question":"Яка товщина бруківки для авто?","answer":"80–100 мм для легкових авто і 100 мм для вантажівок і фур. Пішохідні доріжки — 50–60 мм."},{"question":"Чи потрібен бетон?","answer":"Під саму бруківку зазвичай ні: ущільнений щебінь і відсів працюють краще, бо пропускають воду. Бетон потрібен під бордюри, лотки і на слабких або насипних ґрунтах."},{"question":"Як заповнити шви?","answer":"Гранітним відсівом або дрібним піском, який заміта́ють у шви і проливають водою в кілька заходів. Полімерний пісок тримається довше і не проростає."},{"question":"Скільки служить?","answer":"Камінь — необмежено. Основа за правильної технології — 30 і більше років без переукладання."}],"related":["/vyroby/brukivka","/blog/granitna-chy-vibropresovana-brukivka","/vyroby/dekoratyvnyi-kamin","/kalkulyator"],"materials":["grey-ukraine","maple-red","leopard"],"categories":["brukivka","dekoratyvnyi-kamin"]}'::jsonb, 12) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('kamin-dlya-kaminu-granit-marmur', '{"slug":"kamin-dlya-kaminu-granit-marmur","title":"Камінь для каміну: граніт, мармур чи травертин","h1":"Який камінь обрати для облицювання каміну","description":"Камінь для каміну: граніт, мармур, травертин або лабрадорит. Термостійкість, технічні зазори від топки, клей, догляд і вигляд порталу.","dek":"Порода та вузол облицювання для різних типів камінів.","category":"Проєктування","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Камінний портал це найпомітніший кам’яний виріб у вітальні, і він працює в найскладніших умовах: нагрів, сажа, різкі перепади температури. Природний камінь створений для цього, але порода, вузол і клей мають відповідати типу каміна. Пояснюємо різницю між дров’яним, газовим і електричним і що ми радимо для кожного.","sections":[{"heading":"Який камінь підходить для каміну?","body":"Для дров’яного каміна з відкритою або закритою топкою: граніт або габро на портал і особливо на подіум перед топкою, де падають іскри й вугілля. Для газового: будь-який камінь, включно з мармуром, бо нагрів помірний. Для електричного: обмежень немає, це меблі.\n\nЛабрадорит Volga Blue це один із найефектніших варіантів для порталу: синій спалах кристалів оживає у світлі вогню. Травертин обирають для теплих середземноморських інтер’єрів, але його пори потребують захисту від сажі."},{"heading":"Чим граніт кращий для активної експлуатації?","body":"Граніт не змінює кольору від нагріву до 200–250 °C, не вбирає сажу після просочення, витримує удар полінами і легко миється. На подіумі перед топкою його можна чистити від вугілля жорсткою щіткою. Полірована поверхня відбиває вогонь і додає світла кімнаті.\n\nТермічне розширення граніту невелике, але портал не приклеюють до топки впритул: між металом і каменем лишають зазор 5–10 мм із термостійким ущільнювачем або мінеральною ватою, а плити кладуть на термостійкий клей для каменю."},{"heading":"Коли обрати мармур?","body":"Мармур це класика камінних порталів від Версаля до львівських кам’яниць. Обирайте його для газових і електричних камінів або для дров’яних із закритою топкою, де портал не контактує з полум’ям і має технічний зазор.\n\nНа мармурі помітна сажа й сліди від рук, а кислотні засоби для чищення скла топки протравлюють поверхню. Тому мармуровий портал доглядають лише нейтральними засобами і просочують раз на рік. Bianco Carrara і Nero Marquina найпоширеніший вибір; Crema Marfil дає теплий спокійний портал для світлої вітальні."},{"heading":"Що з термостійкістю і доглядом?","body":"Природний камінь витримує нагрів, якого досягає портал, але не витримує різкого локального нагріву: гарячий чавунний посуд на мармуровому подіумі може лишити слід або тріщину. Тому подіум перед дров’яною топкою робимо з граніту або габро.\n\nДогляд: сажу змивають водою з нейтральним засобом, важкі забруднення компресом із соди. Граніт просочують раз на два-три роки, мармур і травертин щороку. Раз на сезон оглядайте зазор між топкою й каменем: ущільнювач має бути еластичним і без тріщин."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Граніт / габро","Дров’яні каміни, подіум","Термостійкий, миється щіткою"],["Лабрадорит","Акцентний портал","Блиск кристалів у світлі вогню"],["Мармур","Газові й закриті топки, класика","Чутливий до кислот і сажі"],["Травертин","Теплі інтер’єри","Пори просочувати щороку"]]},"faq":[{"question":"Чи витримує мармур жар?","answer":"Помірний нагрів порталу — так. Прямий контакт із полум’ям, іскрами або гарячим металом — ні, для цих зон беремо граніт."},{"question":"Що для дров’яного каміну?","answer":"Граніт або габро на портал і подіум, термостійкий клей, зазор 5–10 мм від топки з еластичним ущільнювачем."},{"question":"Що для класики?","answer":"Мармур Bianco Carrara або Nero Marquina з профільованою кромкою, іноді з різьбленими елементами. Для газової або закритої топки це безпечний вибір."},{"question":"Як чистити портал?","answer":"Нейтральним засобом для каменю і м’якою тканиною. Сажу компресом із соди. Без кислот, особливо на мармурі, і без засобів для чищення скла топки на камені."}],"related":["/vyroby/kaminy","/materialy/labradoryt","/materialy/marmur","/kalkulyator"],"materials":["volga-blue","kometa-black","nero-marquina"],"categories":["kaminy"]}'::jsonb, 13) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('landshaftnyy-kamin-dvir', '{"slug":"landshaftnyy-kamin-dvir","title":"Ландшафтний камінь для двору: види та застосування","h1":"Ландшафтний камінь — як обрати для двору й саду","description":"Ландшафтний камінь для двору: плити для доріжок, підпірні стіни, бордюри, клумби. Морозостійкість, протиковзкий фініш, поєднання з бруківкою і фасадом.","dek":"Камінь для доріжок, клумб, підпірних стін і декоративних зон.","category":"Проєктування","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"У саду камінь працює інакше, ніж у домі: тут немає гарячого посуду, зате є мороз, вода, коріння і газонокосарка. Ландшафтний камінь обирають не за красою на слябі, а за функцією: по чому ходити, що тримати, що підкреслити. Розповідаємо, які вироби з граніту ми робимо для дворів і як вони поєднуються з бруківкою й фасадом.","sections":[{"heading":"Який камінь для ландшафту обрати?","body":"Граніт закриває всі задачі двору: плити для доріжок і терас, бордюри, сходи, підпірні стіни, облицювання клумб і водойм. Він морозостійкий, не боїться води й солі, а термооброблена поверхня не слизька. Пісковик і вапняк м’якші й пористіші, у нашому кліматі лущаться за кілька зим.\n\nДля декоративних зон підходить колотий камінь із відходів виробництва: бут для сухих стінок, окол для клумб. Це доступний спосіб отримати природну фактуру, і ми пропонуємо його разом із основними виробами."},{"heading":"Які види використовують у дворі?","body":"Плити для доріжок і терас: 30–40 мм для укладання на щебінь і пісок, 20 мм на бетонну основу, формат від 300 × 300 до 600 × 900 мм, термооброблений або пиляний фініш. Ступені і садові сходи: масивні блоки або накладні проступи 30–40 мм на бетоні.\n\nПідпірні стіни: гранітні блоки 200–400 мм або облицювальні плити на бетонному ядрі. Бордюри: пиляні або колоті 80–150 мм заввишки, тримають доріжки й газон. Облицювання: клумби, чаші, водойми, вуличні кухні, лави та стільниці для барбекю з термообробленого граніту."},{"heading":"Як поєднати камінь із бруківкою та фасадом?","body":"Одне правило: не більше двох порід у дворі. Наприклад, Grey Ukraine у бруківці й плитах терас плюс Kometa Black у бордюрах, сходах і акцентних смугах. Якщо фасад або цоколь із каменю, ландшафт продовжує його породу.\n\nФініші узгоджуйте за функцією: полірований лише на вертикалях і акцентах, термооброблений усюди, де ходять. Розміри модулів варто кратно узгодити з бруківкою (100 мм), щоб доріжка з плит і заїзд із бруківки стикувались без підрізки."},{"heading":"Як доглядати за ландшафтним каменем?","body":"Двічі на рік промити водою під тиском, особливо тіньові ділянки, де росте мох. Просочення для граніту на вулиці не потрібне, для пісковику й вапняку — гідрофобізатор раз на кілька років.\n\nВзимку пластикова лопата і будь-який протиожеледний засіб, граніт їх витримує. Раз на рік перевірте шви між плитами і бордюрами і за потреби досипте. Рослини з агресивним корінням (верба, тополя, бамбук) саджайте не ближче 2–3 м від доріжок: корені піднімають плити незалежно від породи каменю."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Плити","Доріжки, тераси, зона барбекю","Термооброблений протиковзкий фініш"],["Колотий камінь","Клумби, сухі стінки, акценти","Стабільна основа, дренаж"],["Блоки","Підпірні стіни, сходи в саду","Інженерний розрахунок від 1 м"],["Бордюри","Межі доріжок і газону","На бетонну подушку"]]},"faq":[{"question":"Який камінь морозостійкий?","answer":"Граніт, габро й лабрадорит: водопоглинання нижче 0,2 %, понад 300 циклів заморожування без змін. Пісковик і вапняк у нашому кліматі лущаться."},{"question":"Чи слизький він після дощу?","answer":"Полірований — так, тому на вулиці ми його не кладемо. Термооброблений, бучардований і пиляний граніт протиковзкі мокрими."},{"question":"Як укладати?","answer":"Плити 30–40 мм на ущільнений щебінь і відсів як бруківку, 20 мм на бетон і клей. Бордюри й сходи на бетонну подушку."},{"question":"Як чистити?","answer":"Водою під тиском двічі на рік. Мох змивається, сіль граніту не шкодить, просочення не потрібне."}],"related":["/vyroby/dekoratyvnyi-kamin","/vyroby/brukivka","/blog/ukladannya-granitnoyi-brukivky","/kalkulyator"],"materials":["grey-ukraine","kometa-black","flower-of-ukraine"],"categories":["dekoratyvnyi-kamin","brukivka"]}'::jsonb, 14) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('skilky-koshtue-stilnytsia-z-kamenyu', '{"slug":"skilky-koshtue-stilnytsia-z-kamenyu","title":"Скільки коштує стільниця з каменю: від чого залежить ціна","h1":"Від чого залежить вартість стільниці з каменю","description":"Вартість стільниці з каменю: матеріал, площа і розкрій, товщина, кромка, вирізи, підсилення, доставка й монтаж. Як отримати точний розрахунок.","dek":"Фактори кошторису без оманливих універсальних цін.","category":"Ціни","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"«Скільки коштує стільниця з каменю за метр?» — найчастіше питання, і на нього немає чесної короткої відповіді. Дві стільниці однакової довжини з одного каменю можуть відрізнятись у ціні вдвічі через розкрій, вирізи й кромку. Пояснюємо, з чого складається кошторис, у якому порядку фактори впливають на суму і як отримати точну цифру за один день.","sections":[{"heading":"Скільки коштує стільниця з каменю?","body":"Кошторис складається з чотирьох частин: матеріал (сляб або його частина), обробка (розкрій, кромка, вирізи, полірування торців), додаткові елементи (фартух, підсилення, склеєна кромка) і логістика з монтажем.\n\nМатеріал зазвичай становить від 40 до 60 % суми, обробка 25–40 %, решта на доставку й монтаж. Тому запитання «за метр» вводить в оману: цінник за погонний метр каменю не враховує половини робіт. Орієнтир для конкретних розмірів дає калькулятор на сайті, він рахує саме за цією логікою."},{"heading":"Які фактори впливають на ціну?","body":"Матеріал: порода, бренд, рідкість кольору. Площа і розкрій: ми платимо за сляб цілком, тому важливо, скільки плит потрібно і як деталі лягають на них; стільниця 3,1 м може потребувати двох слябів замість одного.\n\nТовщина: 30 мм дорожче за 20 мм і в матеріалі, і в обробці. Кромка: прямий торець базовий, фаска і скруглення трохи дорожчі, огі, водоспад і склеєна кромка 40–60 мм суттєво дорожчі. Вирізи: кожен виріз під мийку, варильну панель, змішувач або розетку додає роботи, а мийка нижнього монтажу потребує полірування внутрішнього периметра.\n\nМонтаж: поверх, ліфт, довжина деталей, стики на місці, підсилення звисів. Стільниця на п’ятий поверх без ліфта коштує дорожче тієї самої на першому."},{"heading":"Як матеріал впливає на вартість?","body":"Умовно матеріали каталогу діляться на три рівні. Базовий: українські граніти Grey Ukraine, Maple Red, Rosso Santiago і керамограніт стандартних декорів. Середній: габро, лабрадорит, брендовий кварц Vicostone і Caesarstone базових колекцій. Преміальний: мармур, кварцит Taj Mahal, кварц колекцій «під Калакату», Dekton і Neolith.\n\nУсередині одного рівня різниця в ціні невелика, між рівнями відчутна. Ще один нюанс: світлі однорідні матеріали, як правило, дорожчі за темні з рисунком, бо їх складніше виробити без вад. Ціни «від» для кожної колекції вказані на її сторінці в каталозі."},{"heading":"Як швидко отримати точний розрахунок?","body":"Крок перший: калькулятор на сайті з розмірами, типом виробу і матеріалом дає орієнтир за хвилину. Крок другий: надішліть нам план кухні або фото з розмірами, і ми порахуємо розкрій і повний кошторис за день. Крок третій: замір на об’єкті після встановлення меблів фіксує остаточну суму, яка вже не змінюється.\n\nЩоб не переплачувати, продумайте до заміру три речі: чи потрібна склеєна кромка, чи можна перенести шов на місце, де він не помітний, і чи потрібен кам’яний фартух по всій довжині або лише за плитою."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Матеріал","40–60 % кошторису","Рівень породи і кількість слябів"],["Розкрій і товщина","Високий вплив","Довжина понад 3 м = другий сляб"],["Кромка й вирізи","Середній або високий","Склеєна кромка і нижня мийка дорожчі"],["Доставка й монтаж","10–20 %","Поверх, ліфт, стики на місці"]]},"faq":[{"question":"Що дорожче — граніт чи кварц?","answer":"Українські граніти зазвичай доступніші за брендовий кварц. Імпортний граніт рідкісних кольорів і кварц преміальних колекцій коштують приблизно однаково."},{"question":"Чи входить монтаж?","answer":"У кошторисі монтаж окремим рядком, як і доставка. Це дозволяє бачити, за що ви платите, і за бажання замовити лише виготовлення."},{"question":"Як розрахувати самостійно?","answer":"Калькулятор на сайті рахує за розмірами, типом виробу, матеріалом, кромкою й кількістю вирізів. Це орієнтир із точністю приблизно ±15 %, решту уточнює розкрій."},{"question":"Що впливає найбільше?","answer":"Матеріал і кількість слябів. Далі кромка й вирізи. Товщина 30 мм замість 20 мм додає 20–40 %."}],"related":["/kalkulyator","/vyroby/stilnytsi","/porivnyannya","/blog/tovshchyna-stilnytsi-20-30-mm"],"materials":["grey-ukraine","vicostone-bq8270-calacatta","taj-mahal"],"categories":["stilnytsi"]}'::jsonb, 15) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('shcho-take-slyab', '{"slug":"shcho-take-slyab","title":"Що таке сляб і де його застосовують","h1":"Сляб — що це, розміри та застосування","description":"Сляб — велика плита природного або інженерного каменю. Розміри слябів граніту, мармуру, кварцу й керамограніту, товщина, як обрати і що таке залишок.","dek":"Як читати повну плиту, партію, тон і корисну площу.","category":"Ціни","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Сляб (від англійського slab, «плита») це велика плита каменю, розпиляна з блоку і відполірована з одного боку. Саме зі слябів ріжуть стільниці, підвіконня, сходи й облицювання, і саме сляб, а не зразок 10 × 10 см, потрібно дивитись перед замовленням. Пояснюємо, які бувають сляби, які їх розміри і як із них виходить ваша стільниця.","sections":[{"heading":"Що таке сляб?","body":"На кар’єрі камінь видобувають блоками вагою 10–30 тонн. Блок розпилюють на плити товщиною 20 або 30 мм на канатних або дискових верстатах, потім шліфують і полірують лицьову сторону. Готова плита і є сляб: у природного каменю розмір визначає блок, у кварцу й керамограніту — формат заводу.\n\nКожен сляб має номер, партію і фактичні розміри, а природні камені ще й індивідуальний рисунок. Тому в каталозі ми показуємо не «граніт сірий», а конкретні плити з фото, розмірами й статусом наявності."},{"heading":"Які бувають сляби з граніту, мармуру та кварциту?","body":"Гранітні: найбільша група, українські й імпортні, товщина 20 і 30 мм, фініш полірований, матовий, термооброблений або leather. Мармурові: імпорт з Італії, Іспанії, Туреччини, товщина 20 і 30 мм, часто з армувальною сіткою на звороті через крихкість. Кварцитові: Бразилія й Індія, товщина 20 і 30 мм, найтвердіші й найдорожчі з природних.\n\nКварцові (агломерат): заводські плити стандартного формату, товщина 20 і 30 мм, однорідний колір. Керамогранітні: 6, 12 і 20 мм, формат до 3200 × 1600 мм, з декором лише на поверхні або з повним прокрасом залежно від колекції."},{"heading":"Які стандартні розміри має сляб?","body":"Граніт і мармур: від 2400 × 1200 до 3200 × 1900 мм, найчастіше близько 2800 × 1600 мм. Розмір залежить від блоку і породи: українські граніти зазвичай 2400–3000 × 1200–1500 мм. Кварц: стандарт 3050 × 1400 мм, формат Jumbo 3200 × 1600 мм у преміальних колекціях.\n\nКерамограніт: Laminam 3240 × 1620 мм, Neolith 3200 × 1600 мм, Dekton 3200 × 1440 мм. Корисна площа завжди менша за габарит: краї плити мають відступ 20–50 мм із дефектами розпилу, а на природному камені можуть бути тріщини або включення, які ми обходимо при розкрої."},{"heading":"Де застосовують сляби?","body":"Стільниці й острови: із граніту, кварцу, кварциту й керамограніту. Підвіконня і сходи: із граніту, мармуру. Облицювання стін, камінів і фасадів: із будь-якого каменю плитами великого формату, коли потрібен «безшовний» рисунок або bookmatch, дзеркальне поєднання двох сусідніх слябів.\n\nЗалишки слябів після розкрою це окрема категорія: фрагменти 0,5–1,5 м, з яких виходять підвіконня, столики, полиці та невеликі стільниці за нижчою ціною. У нас вони доступні на сторінці залишків із розмірами й фото."}],"table":{"headers":["Критерій","Варіант","Що врахувати"],"rows":[["Гранітний сляб","Стільниці, сходи, облицювання","2400–3200 × 1200–1900 мм, 20/30 мм"],["Мармуровий сляб","Ванні, підвіконня, портали","Часто з сіткою на звороті"],["Кварцитовий сляб","Стільниці та острови","Найтвердіший, до 3 × 1,8 м"],["Кварцовий сляб","Стільниці однорідного кольору","3050 × 1400 або 3200 × 1600 мм"],["Керамогранітний","Стільниці, фасади, фартухи","3200 × 1600 мм, 6–20 мм"]]},"faq":[{"question":"Чим сляб відрізняється від плитки?","answer":"Розміром і тим, що з нього роблять. Плитка це готовий модуль до 1200 мм для укладання на клей. Сляб це заготовка до 3,2 м, з якої виріб ріжуть під ваш розмір."},{"question":"Які розміри має сляб?","answer":"Природний камінь від 2,4 × 1,2 до 3,2 × 1,9 м, кварц 3,05 × 1,4 або 3,2 × 1,6 м, керамограніт 3,2 × 1,6 м. Точні розміри вказані для кожної плити в каталозі."},{"question":"Скільки він коштує?","answer":"Сляб продають за квадратний метр із коефіцієнтом на цілу плиту. Ціна залежить від породи, товщини й партії; у каталозі вказана ціна конкретних слябів у наявності."},{"question":"Як обрати сляб?","answer":"Дивитись цілу плиту при денному світлі, а не зразок: перевірити рисунок, тріщини, включення, узгодити розкладку деталей на плиті. Ми надсилаємо фото й відео сляба і зберігаємо його за вами до розкрою."}],"related":["/vyroby/slyaby","/b2b/slyaby","/zalyshky-slabiv","/kalkulyator"],"materials":["grey-ukraine","taj-mahal","laminam-calacatta"],"categories":["slyaby","stilnytsi"]}'::jsonb, 16) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_articles (slug, data, position) values ('yak-vybraty-kamin-dlya-kukhni', '{"slug":"yak-vybraty-kamin-dlya-kukhni","title":"Як вибрати камінь для кухні: повний гайд 2026","h1":"Як вибрати камінь для кухонної стільниці — повний гайд","description":"Як вибрати камінь для кухні: граніт, кварц, кварцит, керамограніт чи мармур. Порівняння за міцністю, теплом, доглядом, рисунком і бюджетом, товщина й кромка.","dek":"Головний гайд за міцністю, теплом, доглядом і характером рисунка.","category":"Матеріали","readingTime":"3 хв читання","datePublished":"2026-08-20","dateModified":"2026-09-08","intro":"Вибір каменю для кухні починається не з назви матеріалу, а з трьох питань: як ви готуєте, скільки уваги готові приділяти догляду і який характер має мати кухня. Відповівши на них, ви майже автоматично отримаєте один із п’яти матеріалів. У цьому гайді зібрали все, що ми пояснюємо клієнтам на виробництві, з посиланнями на детальні статті.","sections":[{"heading":"Який камінь обрати для кухні?","body":"Готуєте багато, ставите гаряче куди доведеться, любите природний рисунок: граніт. Хочете світлу однорідну поверхню і мінімум догляду, гаряче на підставку: кварц. Хочете світлий природний камінь із прожилками, який не боїться лимона: кварцит. Потрібна тонка сучасна стільниця, на яку можна ставити гаряче: керамограніт. Готові до патини заради красивого мармуру: мармур, але з розумінням наслідків.\n\nЦе спрощена схема, але вона працює у більшості випадків. Далі нюанси."},{"heading":"Граніт, кварц, кварцит, керамограніт чи мармур — у чому різниця?","body":"Граніт: природна порода, твердість 6–7, витримує гаряче, потребує просочення раз на 1–3 роки, кожен сляб унікальний, українські породи доступні за ціною.\n\nКварц: 90 % кварцу зі смолою, без пор, повторюваний колір, чутливий до температури вище 150 °C і до ультрафіолету, не для вулиці.\n\nКварцит: природний, твердість 7, стійкий до кислот, потребує просочення, світлі теплі тони, найдорожчий із природних.\n\nКерамограніт: спечена плита 12 мм, не боїться нічого, крім удару в ребро, найлегший, потребує суцільної основи й фаски на кромці.\n\nМармур: кальцит, твердість 3–4, травиться кислотами, найкрасивіший рисунок, для кухні з обережним господарем або для острова, де не готують."},{"heading":"Що врахувати за міцністю, доглядом і бюджетом?","body":"Міцність на удар і подряпини: кварцит і граніт, потім кварц і керамограніт (крихкі краї), потім мармур. Стійкість до плям без просочення: кварц і керамограніт, потім кварцит і граніт із просоченням, потім мармур.\n\nДогляд: кварц і керамограніт нічого, крім мийки; граніт і кварцит водний тест і просочення; мармур просочення щороку і нейтральна хімія завжди. Бюджет за зростанням: українські граніти і базовий керамограніт, далі кварц і габро, далі мармур, кварцит і преміальні колекції кварцу й керамограніту."},{"heading":"Яка товщина й обробка потрібні?","body":"Товщина: 20 мм для стандартної кухні на всіх матеріалах, 30 мм для довгих консолей або масивного стилю, 12 мм для керамограніту зі склеєною кромкою. Кромка: прямий торець або фаска базово, скруглення R3 для родин із дітьми, склеєна 40 мм для вигляду товстої плити.\n\nФініш: полірований показує рисунок і легше миється, матовий (honed) ховає відбитки й травлення на мармурі, leather на темному граніті додає тактильності й ховає подряпини. Для кухні з вікном на південь темний полірований камінь дасть відблиски, врахуйте це."},{"heading":"Як замовити й розрахувати вартість?","body":"Порахуйте орієнтир у калькуляторі, оберіть дві-три колекції в каталозі і напишіть нам із планом кухні. Ми надішлемо фото слябів у наявності, кошторис із розкроєм і дату заміру. Після заміру ви затверджуєте розкладку деталей на конкретній плиті, і за один-два тижні стільниця стоїть на кухні.\n\nЯкщо сумніваєтесь між двома матеріалами, приїжджайте на виробництво в Костопіль або замовте зразки: на них можна провести домашній тест лимоном, гарячою чашкою і ножем, після якого вибір стає очевидним."}],"table":{"headers":["Матеріал","Сильна сторона","Що врахувати"],"rows":[["Граніт","Тепло, удар, унікальний рисунок","Просочення раз на 1–3 роки"],["Кварц","Без пор, повторюваний колір","Підставка під гаряче, не для вулиці"],["Кварцит","Твердість і світлий природний тон","Погодження сляба, вища ціна"],["Керамограніт","Тонкість, гаряче, UV-стійкість","Крихкі краї, суцільна основа"],["Мармур","Найкрасивіший рисунок","Кислоти, патина, догляд щороку"]]},"faq":[{"question":"Що найпрактичніше?","answer":"Кварц для світлої кухні, граніт для будь-якої іншої. Обидва прощають щоденне користування, різниця лише в гарячому посуді й просоченні."},{"question":"Що обрати для родини з дітьми?","answer":"Кварц або граніт зі скругленою кромкою R3. Керамограніт гірше переносить удари іграшками в ребро, мармур потребує уваги, якої в родині з дітьми зазвичай немає."},{"question":"Що потребує герметизації?","answer":"Граніт, кварцит і мармур. Кварц і керамограніт не мають пор і не просочуються."},{"question":"З чого почати вибір?","answer":"Зі сценарію: як готуєте і скільки догляду готові давати. Потім із кольору й рисунка в каталозі, потім із калькулятора і зразків."}],"related":["/blog/kvarc-chy-granit-stilnytsia","/blog/stilnytsia-z-kvarcytu-taj-mahal","/blog/tovshchyna-stilnytsi-20-30-mm","/blog/keramogranit-laminam-neolith-stilnytsia","/blog/marmur-u-vanniy-kimnati","/blog/yak-doglyadaty-za-granitnoyu-stilnytseyu","/blog/skilky-koshtue-stilnytsia-z-kamenyu","/vyroby/stilnytsi","/porivnyannya","/kalkulyator"],"materials":["grey-ukraine","caesarstone-calacatta-nuvo","taj-mahal","laminam-calacatta","bianco-carrara"],"categories":["stilnytsi"]}'::jsonb, 17) on conflict (slug) do update set data = excluded.data;
insert into public.stilnytsi_slabs (id, data, position) values ('SM–001', '{"id":"SM–001","collectionSlug":"grey-ukraine","collection":"Покостівський граніт","material":"granit","tone":"світло-сірий","dimensions":[302,154],"thickness":20,"finish":"Полірований","lot":"PK-2608-01","origin":"Україна","status":"В наявності","quantity":2,"price":3640,"image":"/materials/granite-catalog.webp","availability":"Доступний до резерву","uniqueness":"Фактична плита має унікальний рисунок, тон і мінеральні включення.","alt":"Сляб Покостівський граніт, артикул SM–001"}'::jsonb, 0) on conflict (id) do update set data = excluded.data;
