insert into public.stilnytsi_settings (key, data) values ('faq', '{"category":[{"question":"Як обрати матеріал для щоденного використання?","answer":"Почніть зі сценарію: температура, вода, плями та інтенсивність. Для кухні зазвичай важливі непористість або висока твердість, а остаточний вибір роблять після перегляду цілого сляба."},{"question":"Чи однаковий рисунок у всіх слябів?","answer":"Ні. Природний камінь має унікальні прожилки й відтінки; кварц і керамограніт повторюваніші, але партії також можуть різнитися."},{"question":"Скільки триває виготовлення?","answer":"Строк залежить від матеріалу, геометрії та завантаження виробництва. Після заміру й затвердження креслення команда підтвердить точний календар."},{"question":"Чи можна побачити камінь наживо перед замовленням?","answer":"Так. Перед запуском у виробництво ми показуємо фото та відео конкретного сляба, з якого буде виготовлено ваш виріб, — ви затверджуєте саме той камінь, який отримаєте."},{"question":"Що входить у монтаж?","answer":"Склад робіт визначається проєктом: доставка, підйом, встановлення, стикування й герметизація. У кошторисі кожну позицію показуємо окремо."},{"question":"Як доглядати за поверхнею?","answer":"Щодня використовуйте м’яку тканину й pH-нейтральний засіб. Натуральний камінь може потребувати періодичного просочення; кислоти особливо небажані для мармуру."}],"calculator":[{"question":"Як обрати матеріал для щоденного використання?","answer":"Почніть зі сценарію: температура, вода, плями та інтенсивність. Для кухні зазвичай важливі непористість або висока твердість, а остаточний вибір роблять після перегляду цілого сляба."},{"question":"Чи однаковий рисунок у всіх слябів?","answer":"Ні. Природний камінь має унікальні прожилки й відтінки; кварц і керамограніт повторюваніші, але партії також можуть різнитися."},{"question":"Скільки триває виготовлення?","answer":"Строк залежить від матеріалу, геометрії та завантаження виробництва. Після заміру й затвердження креслення команда підтвердить точний календар."},{"question":"Чи можна побачити камінь наживо перед замовленням?","answer":"Так. Перед запуском у виробництво ми показуємо фото та відео конкретного сляба, з якого буде виготовлено ваш виріб, — ви затверджуєте саме той камінь, який отримаєте."},{"question":"Що входить у монтаж?","answer":"Склад робіт визначається проєктом: доставка, підйом, встановлення, стикування й герметизація. У кошторисі кожну позицію показуємо окремо."}],"b2b":[{"question":"Чи однаковий рисунок у всіх слябів?","answer":"Ні. Природний камінь має унікальні прожилки й відтінки; кварц і керамограніт повторюваніші, але партії також можуть різнитися."},{"question":"Скільки триває виготовлення?","answer":"Строк залежить від матеріалу, геометрії та завантаження виробництва. Після заміру й затвердження креслення команда підтвердить точний календар."},{"question":"Чи можна побачити камінь наживо перед замовленням?","answer":"Так. Перед запуском у виробництво ми показуємо фото та відео конкретного сляба, з якого буде виготовлено ваш виріб, — ви затверджуєте саме той камінь, який отримаєте."},{"question":"Як отримати trade-умови?","answer":"Заповніть коротку форму із роллю та даними студії. Умови залежать від типу партнерства, обсягу й регулярності замовлень."},{"question":"Чи надаєте CAD/BIM?","answer":"Так, доступні технічні вузли та файли для погоджених матеріалів і типових виробів."}],"geo":[{"question":"Як обрати матеріал для щоденного використання?","answer":"Почніть зі сценарію: температура, вода, плями та інтенсивність. Для кухні зазвичай важливі непористість або висока твердість, а остаточний вибір роблять після перегляду цілого сляба."},{"question":"Чи однаковий рисунок у всіх слябів?","answer":"Ні. Природний камінь має унікальні прожилки й відтінки; кварц і керамограніт повторюваніші, але партії також можуть різнитися."},{"question":"Скільки триває виготовлення?","answer":"Строк залежить від матеріалу, геометрії та завантаження виробництва. Після заміру й затвердження креслення команда підтвердить точний календар."},{"question":"Чи можна побачити камінь наживо перед замовленням?","answer":"Так. Перед запуском у виробництво ми показуємо фото та відео конкретного сляба, з якого буде виготовлено ваш виріб, — ви затверджуєте саме той камінь, який отримаєте."},{"question":"Що входить у монтаж?","answer":"Склад робіт визначається проєктом: доставка, підйом, встановлення, стикування й герметизація. У кошторисі кожну позицію показуємо окремо."},{"question":"Як доглядати за поверхнею?","answer":"Щодня використовуйте м’яку тканину й pH-нейтральний засіб. Натуральний камінь може потребувати періодичного просочення; кислоти особливо небажані для мармуру."}]}'::jsonb) on conflict (key) do update set data = excluded.data;
insert into public.stilnytsi_settings (key, data) values ('support', '{"harantiya":{"eyebrow":"Підтримка","title":"Гарантія без дрібного шрифту.","copy":"Фіксуємо матеріал, обробку, монтаж і гарантійні умови у вашому договорі.","sections":[{"title":"Що покриває","copy":"Відповідність погодженому кресленню, якість виробничої обробки та виконаних нами монтажних робіт."},{"title":"Природа каменю","copy":"Жили, кристали, пори й зміни тону є природними особливостями, якщо вони були погоджені на слябі."},{"title":"Звернення","copy":"Надішліть номер замовлення, фото загального вигляду й крупний план. Ми відповімо протягом робочого дня."}],"faq":[{"question":"Який строк гарантії?","answer":"Строк залежить від виробу, матеріалу та складу робіт і завжди фіксується в договорі."},{"question":"Чи покриває гарантія сколи від удару?","answer":"Механічні пошкодження під час експлуатації не є виробничим дефектом, але ми можемо оцінити ремонт."}]},"dostavka-i-montazh":{"eyebrow":"Логістика","title":"Доставка й монтаж — один керований процес.","copy":"Перевіряємо доступ, упаковуємо деталі за монтажною послідовністю і погоджуємо вікно робіт.","sections":[{"title":"Перед виїздом","copy":"Уточнюємо поверх, ліфт, проходи, стан меблів та готовність основ."},{"title":"На об’єкті","copy":"Захищаємо маршрут, виставляємо деталі, стикуємо, герметизуємо й прибираємо робочу зону."},{"title":"Приймання","copy":"Разом перевіряємо геометрію, шви й поверхню та передаємо правила першого догляду."}],"faq":[{"question":"Чи входить підйом у доставку?","answer":"Підйом розраховуємо окремо після перевірки ваги деталей і доступу."},{"question":"Коли можна користуватися поверхнею?","answer":"Після монтажу майстер повідомить час полімеризації конкретного герметика."}]},"dohliad":{"eyebrow":"Практичний гайд","title":"Догляд, який зберігає характер каменю.","copy":"Короткі правила для щоденного очищення, плям і періодичного захисту.","sections":[{"title":"Щодня","copy":"М’яка тканина, тепла вода та pH-нейтральний засіб. Рідину краще прибирати одразу."},{"title":"Чого уникати","copy":"Кислот, абразивних порошків, металевих губок і невідомих концентратів."},{"title":"Просочення","copy":"Потребу перевіряють тестом із краплею води; частота залежить від породи та інтенсивності."}],"faq":[{"question":"Чи можна використовувати оцет?","answer":"Ні для мармуру й інших кальцитових порід: кислота матує поверхню."},{"question":"Як прибрати пляму?","answer":"Не тріть її навмання. Сфотографуйте пляму й уточніть речовину — метод залежить від її складу."}]}}'::jsonb) on conflict (key) do update set data = excluded.data;
insert into public.stilnytsi_settings (key, data) values ('comparisons', '{"kvarc-vs-granit":{"title":"Кварц чи граніт?","seoTitle":"Кварц чи граніт — порівняння","left":"Кварц","right":"Граніт","verdict":"Кварц простіший у догляді; граніт краще переносить тепло й дає унікальний природний рисунок.","rows":[["Походження","Мінеральний наповнювач і смола","Природна магматична порода"],["Подряпини","Добра стійкість","Висока стійкість"],["Гаряче","Потрібна підставка","Краще переносить температуру"],["Плями","Непористий","Потребує просочення"],["Зовні","Залежить від виробника","Підходить за правильного монтажу"]]},"kvartsyt-vs-marmur":{"title":"Кварцит чи мармур?","seoTitle":"Кварцит чи мармур — порівняння","left":"Кварцит","right":"Мармур","verdict":"Кварцит практичніший для активної кухні; мармур обирають за пластичний рисунок і готовність прийняти патину.","rows":[["Твердість","Висока","Середня"],["Кислоти","Стійкіший","Чутливий до травлення"],["Тепло","Висока стійкість","Добра стійкість"],["Рисунок","Кристалічний, контрастний","М’який, пластичний"],["Догляд","Просочення за потреби","Делікатний догляд і захист"]]},"keramogranit-vs-naturalnyi-kamin":{"title":"Керамограніт чи природний камінь?","seoTitle":"Керамограніт чи природний камінь","left":"Керамограніт","right":"Природний камінь","verdict":"Керамограніт дає тонкість і повторюваність; природний камінь — ремонтопридатність, глибину та неповторність.","rows":[["Походження","Промислово спечена плита","Природна порода"],["Товщина","Зазвичай 6–12 мм","Зазвичай 20–30 мм"],["Рисунок","Повторюваний декор","Кожен сляб унікальний"],["Край","Потребує точного підсилення","Широкий вибір профілів"],["Зовні","Стабільний до UV","Залежить від породи"]]}}'::jsonb) on conflict (key) do update set data = excluded.data;
insert into public.stilnytsi_settings (key, data) values ('geo', '{"rivne":{"locative":"Рівному","context":"Регулярно працюємо з об’єктами Рівного та передмістя.","distance":"Виїзд із виробництва в Костополі погоджуємо за адресою."},"kyiv":{"locative":"Києві","context":"Комплектуємо приватні й комерційні інтер’єри в Києві.","distance":"Логістику, підйом і монтаж плануємо окремим вікном."},"kostopil":{"locative":"Костополі","context":"Виробництво і шоурум Stone Memory розташовані в Костополі.","distance":"Можна переглянути сляб і погодити розкладку безпосередньо в цеху."},"lutsk":{"locative":"Луцьку","context":"Працюємо зі стільницями та архітектурними деталями для Луцька.","distance":"Доставку з Костополя об’єднуємо з професійним монтажем."}}'::jsonb) on conflict (key) do update set data = excluded.data;
insert into public.stilnytsi_settings (key, data) values ('professional', '{"segments":[{"slug":"arkhitektory","name":"Архітекторам","copy":"Специфікації, BIM-ready вузли, фото фактичних слябів і погоджена розкладка.","image":"/professional/arkhitektory.webp","alt":"Архітектор погоджує креслення кам’яних деталей у виробництві Stone Memory","deliverables":["Підбір за референсом і бюджетом","DWG-вузли та карти розкрою","Фото та відео фактичної партії"]},{"slug":"dyzaynery","name":"Дизайнерам","copy":"Матеріальна бібліотека, консультація щодо фінішів і спільна презентація клієнту.","image":"/professional/dyzaynery.webp","alt":"Дизайнер порівнює фактури натурального каменю Stone Memory","deliverables":["Спільний підбір матеріалу з клієнтом","Колажі та фото конкретних слябів","Авторський супровід виробництва"]},{"slug":"zabudovnyky","name":"Забудовникам","copy":"Серійні специфікації, контроль партій і поетапна логістика на об’єкт.","image":"/professional/zabudovnyky.webp","alt":"Контроль партії кам’яних плит для забудовника","deliverables":["Оптові партії та резерв","Контроль відтінку між поставками","Графік виготовлення й монтажу"]},{"slug":"meblevi-vyrobnytstva","name":"Меблевим виробництвам","copy":"Стільниці й деталі за кресленнями з контрольними шаблонами.","image":"/professional/meblevi-vyrobnytstva.webp","alt":"Кам’яна стільниця підготовлена для меблевого виробництва","deliverables":["Обмін DXF/DWG","Серійна обробка крайки","Пакування по модулях"]}],"specials":{"spetsyfikatsiyi":{"title":"Специфікації","seoTitle":"Специфікації та файли","copy":"Технічне рішення до першого різу.","items":["Надішліть плани, розгортки та вимоги до навантаження.","Отримайте shortlist матеріалів із ризиками й альтернативами.","Погодьте сляб, фініш, товщину, крайку та шви.","Ми підготуємо специфікацію, карту розкрою й комерційну пропозицію."]},"prysi":{"title":"Trade-ціни","seoTitle":"Trade-ціни","copy":"Прозорі умови для регулярної співпраці.","items":["Персональний менеджер проєкту","Резервування конкретних слябів","Пріоритетний прорахунок креслень","Технічна бібліотека й карти розкрою","Прозорі trade-умови за обсягом","Фотофіксація виробництва"]},"tendery":{"title":"Тендери та опт","seoTitle":"Тендери та опт","copy":"Керована партія, документація й графік постачання.","items":["Відомість обсягів і альтернативи","Марковані фото контрольної партії","Паспорт партії та графік поставок","Поетапне пакування для об’єкта"]}},"specificationSteps":["Надішліть плани, розгортки та вимоги до навантаження.","Отримайте shortlist матеріалів із ризиками й альтернативами.","Погодьте сляб, фініш, товщину, крайку та шви.","Ми підготуємо специфікацію, карту розкрою й комерційну пропозицію."],"tradeBenefits":["Персональний менеджер проєкту","Резервування конкретних слябів","Пріоритетний прорахунок креслень","Технічна бібліотека й карти розкрою","Прозорі trade-умови за обсягом","Фотофіксація виробництва"],"b2bFaq":[{"q":"Чи працюєте за DWG і DXF?","a":"Так. Приймаємо креслення, перевіряємо допуски й повертаємо карту деталей на погодження."},{"q":"Як резервується партія?","a":"Після погодження відтінку фіксуємо номери слябів і строк резерву в пропозиції."},{"q":"Які матеріали надаєте для тендеру?","a":"Готуємо технічні карти, фото фактичної партії, дані про походження, фініш і товщину."},{"q":"Як формується trade-ціна?","a":"Залежить від матеріалу, повторюваності деталей, обсягу, строків і складу робіт."}]}'::jsonb) on conflict (key) do update set data = excluded.data;
insert into public.stilnytsi_settings (key, data) values ('service', '{"promises":{"response":"Відповідаємо протягом робочого дня","turnaround":"Орієнтовний термін уточнюємо після заміру та вибору матеріалу","warranty":"Гарантійний строк фіксуємо в договорі для конкретного виробу"},"workSteps":[["01","Запит","З’ясовуємо задачу, розміри, місто й очікуваний результат."],["02","Підбір","Показуємо матеріали, сляби, фініші та релевантні альтернативи."],["03","Зразок і кошторис","Погоджуємо зразок, орієнтовну вартість і склад робіт."],["04","Замір і шаблон","Перевіряємо геометрію, вузли, доступ і готовність основ."],["05","Виготовлення","Робимо карту розкрою, обробляємо деталі та контролюємо якість."],["06","Доставка й монтаж","Пакуємо, привозимо, монтуємо та передаємо рекомендації з догляду."]]}'::jsonb) on conflict (key) do update set data = excluded.data;
